INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C1','sci',3,1,'u1',1,'공으로 페트병 넘어뜨리기 — 손으로 공을 밀면 공에 힘이 작용하고, 굴러간 공이 페트병에 부딪쳐 페트병이 넘어짐',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C2','sci',3,1,'u1',1,'힘의 세기 — 세게 밀면 공이 빠르고 멀리 굴러가고, 약하게 밀면 천천히 가까이 감 · 힘의 세기를 조절하면 결과가 달라짐',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C3','sci',3,1,'u1',1,'미는 힘과 당기는 힘 — 미는 힘 = 나에게서 멀어지게 · 당기는 힘 = 나에게 가까이 · 밀기도 당기기도 모두 힘',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C4','sci',3,1,'u1',1,'힘을 받은 물체의 변화 — 힘을 받으면 물체가 움직이거나 모양이 변함(공을 차면 굴러감 · 찰흙을 누르면 납작해짐)',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C5','sci',3,1,'u1',1,'공 놀이 안전 — 공과 페트병을 친구에게 던지지 않기 · 주변을 살피고 바닥에서 굴리기 · 놀이 뒤 정리',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
