INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u1-C8','sci',3,1,'u1',2,'멈추게 하는 힘 — 움직이던 물체를 잡아 멈추게 함(흔들리는 그네 잡기 · 날아오는 공 받기 · 자전거 브레이크) · 힘은 멈추게도 함',ARRAY['[4과01-01] 일상생활에서 물체를 밀거나 당기는 경험을 통해 힘을 느끼고, 물체의 무게에 따라 드는 힘의 크기를 비교할 수 있다(성취기준 초안 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
