INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X01','sci',3,'u1',ARRAY['SC3-1-u1-C3']::text[],'미는 힘과 당기는 힘을 뒤바꾸거나 당기기는 힘이 아니라고 여긴다','멀어지게 · 가까이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X02','sci',3,'u1',ARRAY['SC3-1-u1-C10','SC3-1-u1-C6']::text[],'바라보기·듣기·생각하기처럼 물체에 힘을 주지 않는 일도 힘을 쓴 것이라고 여긴다','밀거나 당겼나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X03','sci',3,'u1',ARRAY['SC3-1-u1-C2']::text[],'약하게 밀수록 더 멀리 가거나 힘의 세기와 결과가 관계없다고 여긴다','세게 밀면 멀리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X04','sci',3,'u1',ARRAY['SC3-1-u1-C4']::text[],'힘을 받아도 물체에 아무 변화가 없거나 색깔이 바뀐다고 여긴다','움직이거나 모양이 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X05','sci',3,'u1',ARRAY['SC3-1-u1-C9']::text[],'물체가 스스로 힘을 가져 저절로 움직일 수 있다고 여긴다','힘을 주어야 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X06','sci',3,'u1',ARRAY['SC3-1-u1-C8']::text[],'힘은 물체를 움직이게만 하고 멈추게 하지는 않는다고 여긴다','멈추게도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X07','sci',3,'u1',ARRAY['SC3-1-u1-C7','SC3-1-u1-C8']::text[],'움직이게 하는 일과 멈추게 하는 일을 뒤바꾼다','처음과 나중을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X08','sci',3,'u1',ARRAY['SC3-1-u1-C5','SC3-1-u1-C15']::text[],'놀이·실험 안전을 지키지 않는다(던지기 · 무리해서 들기 · 장난)','안전이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X09','sci',3,'u1',ARRAY['SC3-1-u1-C11','SC3-1-u1-C13']::text[],'가벼운 물체가 더 큰 힘이 들거나 무게와 드는 힘이 관계없다고 여긴다','무거울수록 큰 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X10','sci',3,'u1',ARRAY['SC3-1-u1-C12']::text[],'당길 때는 물체의 무게와 상관없이 같은 힘이 든다고 여긴다','당길 때도 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X11','sci',3,'u1',ARRAY['SC3-1-u1-C14']::text[],'예상만 하고 직접 비교하지 않거나 예상과 다른 결과를 고쳐 적는다','예상 → 해 보기 → 비교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X12','sci',3,'u1',ARRAY['SC3-1-u1-C13','SC3-1-u1-C16']::text[],'크기가 크면 늘 더 무겁고 크기가 같으면 무게도 같다고 여긴다','크기 ≠ 무게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X13','sci',3,'u1',ARRAY['SC3-1-u1-C20']::text[],'수평대·시소가 가벼운 쪽으로 기울거나 위로 올라간 쪽이 더 무겁다고 여긴다','무거운 쪽이 내려가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X14','sci',3,'u1',ARRAY['SC3-1-u1-C18']::text[],'받침점에서 거리를 다르게 놓아도 무게를 바르게 비교할 수 있다고 여긴다','같은 거리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X15','sci',3,'u1',ARRAY['SC3-1-u1-C16','SC3-1-u1-C17']::text[],'무게와 수평의 뜻을 뒤바꾸거나 수평을 기운 상태로 안다','수평 = 기울지 않음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X16','sci',3,'u1',ARRAY['SC3-1-u1-C19']::text[],'무게가 같아도 기울거나 무게가 달라도 수평이라고 여긴다','같으면 수평') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X17','sci',3,'u1',ARRAY['SC3-1-u1-C21']::text[],'세 물체를 한꺼번에 올리거나 생김새로 무게 순서를 정한다','두 개씩 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X18','sci',3,'u1',ARRAY['SC3-1-u1-C22']::text[],'수평인 시소에 한 명이 더 앉으면 반대쪽으로 기울거나 그대로라고 여긴다','더 앉은 쪽으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X19','sci',3,'u1',ARRAY['SC3-1-u1-C23']::text[],'손으로 들어 보면 누구나 똑같이 정확하게 무게를 알 수 있다고 여긴다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X20','sci',3,'u1',ARRAY['SC3-1-u1-C24']::text[],'저울도 사람마다 다른 값을 알려 주거나 어림일 뿐이라고 여긴다','저울은 정확해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X21','sci',3,'u1',ARRAY['SC3-1-u1-C25']::text[],'무게의 단위를 cm·L·분처럼 다른 양의 단위로 안다','g · kg') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X22','sci',3,'u1',ARRAY['SC3-1-u1-C26','SC3-1-u1-C27']::text[],'용수철저울과 전자저울이 무게를 알려 주는 방법을 뒤바꾼다','눈금 · 숫자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X23','sci',3,'u1',ARRAY['SC3-1-u1-C26']::text[],'용수철저울을 세게 당겨도 되거나 무거울수록 용수철이 덜 늘어난다고 여긴다','무거울수록 많이 늘어나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X24','sci',3,'u1',ARRAY['SC3-1-u1-C28']::text[],'저울이 쓰이는 곳을 길이·온도·소리를 다루는 일로 잘못 안다','무게를 재는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X25','sci',3,'u1',ARRAY['SC3-1-u1-C31']::text[],'도구를 쓰면 힘이 더 들거나 똑같이 든다고 여긴다','도구 = 작은 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X26','sci',3,'u1',ARRAY['SC3-1-u1-C29','SC3-1-u1-C30']::text[],'지레와 빗면의 뜻을 뒤바꾸거나 저울·수평대와 헷갈린다','막대를 받침 · 비스듬한 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X27','sci',3,'u1',ARRAY['SC3-1-u1-C32']::text[],'지레 도구와 빗면 도구의 예를 뒤바꾼다','가위·시소 · 계단·경사로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X28','sci',3,'u1',ARRAY['SC3-1-u1-C33']::text[],'무거운 물체는 한 사람이 맨손으로만 옮겨야 한다고 여긴다','힘을 합치거나 도구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X29','sci',3,'u1',ARRAY['SC3-1-u1-C35']::text[],'상황에 맞지 않는 방법(맨손으로 던지기 · 발로 차기)이나 엉뚱한 도구를 고른다','알맞은 도구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X30','sci',3,'u1',ARRAY['SC3-1-u1-C34']::text[],'도구는 공장 같은 특별한 곳에만 있다고 여긴다','우리 주변 곳곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X31','sci',3,'u1',ARRAY['SC3-1-u1-C36']::text[],'찾은 도구를 친구와 나누는 것은 도움이 안 된다고 여긴다','나누면 더 많이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X32','sci',3,'u1',ARRAY['SC3-1-u1-C37']::text[],'도구는 생활과 관계없거나 일을 더 불편하게 한다고 여긴다','생활이 편해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X33','sci',3,'u1',ARRAY['SC3-1-u1-C38']::text[],'입는 로봇을 사람 없이 혼자 일하는 기계나 엉뚱한 일을 하는 기계로 안다','몸에 입어 힘을 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X34','sci',3,'u1',ARRAY['SC3-1-u1-C39']::text[],'입는 로봇을 입으면 힘이 더 들거나 똑같다고 여긴다','작은 힘으로 번쩍') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X35','sci',3,'u1',ARRAY['SC3-1-u1-C40']::text[],'입는 로봇이 힘이 거의 들지 않는 곳에서 쓰이거나 한 곳에서만 쓰인다고 여긴다','힘든 일을 하는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X36','sci',3,'u1',ARRAY['SC3-1-u1-C41']::text[],'입는 로봇이 지레·빗면 같은 도구와 관계없거나 무게를 재는 기계라고 여긴다','작은 힘으로 들게 돕는 도구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X37','sci',3,'u1',ARRAY['SC3-1-u1-C1']::text[],'힘이 눈에 보이는 물체라고 여긴다','보이지 않아도 작용해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u1-X38','sci',3,'u1',ARRAY['SC3-1-u1-C6']::text[],'힘은 과학 실험 같은 특별한 때에만 쓰인다고 여긴다','생활 곳곳에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#1','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C1',1,'mc','auto','공으로 페트병을 넘어뜨리려면 어떻게 해야 하나요?',ARRAY['SC3-1-u1-X02','SC3-1-u1-X05','SC3-1-u1-X04']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C1","difficulty":1,"kind":"mc","stem":"공으로 페트병을 넘어뜨리려면 어떻게 해야 하나요?","options":[{"t":"공에 힘을 주어 밀어요","correct":true},{"t":"공을 가만히 바라봐요","mis":"SC3-1-u1-X02"},{"t":"공이 저절로 굴러가기를 기다려요","mis":"SC3-1-u1-X05"},{"t":"공에 예쁜 색을 칠해요","mis":"SC3-1-u1-X04"}],"explanation":["공을 어떻게 했나요?","손으로 밀었어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#2','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C3',1,'mc','auto','물체를 나에게서 멀어지게 하는 힘은 무엇인가요?',ARRAY['SC3-1-u1-X01','SC3-1-u1-X02','SC3-1-u1-X04']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C3","difficulty":1,"kind":"mc","stem":"물체를 나에게서 멀어지게 하는 힘은 무엇인가요?","options":[{"t":"미는 힘","correct":true},{"t":"당기는 힘","mis":"SC3-1-u1-X01"},{"t":"바라보는 힘","mis":"SC3-1-u1-X02"},{"t":"색이 바뀌는 힘","mis":"SC3-1-u1-X04"}],"explanation":["카트를 떠올려요.","앞으로 밀어요.","미는 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#3','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C2',1,'ox','auto','공을 세게 밀면 약하게 밀 때보다 더 멀리 굴러가요.',ARRAY['SC3-1-u1-X03']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C2","difficulty":1,"kind":"ox","stem":"공을 세게 밀면 약하게 밀 때보다 더 멀리 굴러가요.","answer":"O","reason_options":[{"t":"힘을 세게 줄수록 공이 더 멀리 굴러가기 때문에","correct":true},{"t":"힘의 세기와 상관없이 공은 늘 같은 거리만 가기 때문에","mis":"SC3-1-u1-X03"}],"mis":"SC3-1-u1-X03","explanation":["세게 밀어 본 때를 떠올려요.","더 멀리 갔어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#4','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C3',1,'sa','auto','줄을 내 쪽으로 가까이 끌어오는 것은 「미는 힘」과 「○○○ 힘」 가운데 무엇인가요? ○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C3","difficulty":1,"kind":"sa","stem":"줄을 내 쪽으로 가까이 끌어오는 것은 「미는 힘」과 「○○○ 힘」 가운데 무엇인가요? ○○○에 알맞은 말을 쓰세요.","answer":["당기는"],"explanation":["줄다리기를 떠올려요.","내 쪽으로 와요.","「당기는」이에요."],"mis":"SC3-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#5','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C4',2,'match','auto','힘을 준 일과 일어난 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C4","difficulty":2,"kind":"match","stem":"힘을 준 일과 일어난 일을 알맞게 이으세요.","pairs":[{"l":"공을 발로 차요","r":"공이 굴러가요"},{"l":"찰흙을 손으로 눌러요","r":"찰흙 모양이 변해요"},{"l":"문을 밀어요","r":"문이 열려요"}],"mis":"SC3-1-u1-X04","explanation":["힘을 주면 무엇이 변하나요?","움직이거나 모양이 변해요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#6','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C4',2,'mc','auto','힘을 받은 물체에 일어나는 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X04','SC3-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C4","difficulty":2,"kind":"mc","stem":"힘을 받은 물체에 일어나는 일로 알맞은 것은 무엇인가요?","options":[{"t":"움직이거나 모양이 변해요","correct":true},{"t":"아무 일도 일어나지 않아요","mis":"SC3-1-u1-X04"},{"t":"색깔이 저절로 바뀌어요","mis":"SC3-1-u1-X04"},{"t":"힘이 눈에 보이게 돼요","mis":"SC3-1-u1-X37"}],"explanation":["공과 찰흙을 떠올려요.","두 가지 변화예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#7','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C3',2,'ox','auto','서랍을 열 때 손잡이를 내 쪽으로 끄는 것은 미는 힘이에요.',ARRAY['SC3-1-u1-X01']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C3","difficulty":2,"kind":"ox","stem":"서랍을 열 때 손잡이를 내 쪽으로 끄는 것은 미는 힘이에요.","answer":"X","reason_options":[{"t":"서랍을 나에게 가까이 끌어오니 당기는 힘이기 때문에","correct":true},{"t":"손을 쓰는 일은 모두 미는 힘이기 때문에","mis":"SC3-1-u1-X01"}],"mis":"SC3-1-u1-X01","explanation":["서랍이 어디로 오나요?","내 쪽으로 와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#8','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C2',2,'mc','auto','공 놀이 기록 ②처럼 공이 페트병까지 가지 못했을 때 어떻게 하면 좋을까요?',ARRAY['SC3-1-u1-X03','SC3-1-u1-X02','SC3-1-u1-X05']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C2","difficulty":2,"kind":"mc","stem":"공 놀이 기록 ②처럼 공이 페트병까지 가지 못했을 때 어떻게 하면 좋을까요?","options":[{"t":"공을 조금 더 세게 밀어요","correct":true},{"t":"공을 더 약하게 밀어요","mis":"SC3-1-u1-X03"},{"t":"공을 그냥 바라봐요","mis":"SC3-1-u1-X02"},{"t":"공이 저절로 굴러가기를 기다려요","mis":"SC3-1-u1-X05"}],"explanation":["②와 ③을 견줘요.","③에서는 넘어졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 페트병 두 개를 바닥에 세웠다.","② 공을 약하게 밀었더니 천천히 굴러가다 페트병에 닿지 못했다.","③ 공을 세게 밀었더니 빠르게 굴러가 페트병이 넘어졌다.","④ 찰흙을 손으로 꾹 눌렀더니 납작해졌다."],"title":"공 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_basic#9','sci',3,1,'u1','L01','g3_1_sci_u1_L01_basic','lesson_basic','SC3-1-u1-C5',2,'mc','auto','페트병 넘어뜨리기 놀이를 할 때 지킬 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C5","difficulty":2,"kind":"mc","stem":"페트병 넘어뜨리기 놀이를 할 때 지킬 일로 알맞은 것은 무엇인가요?","options":[{"t":"공을 바닥에서 굴려 밀고 친구에게 던지지 않아요","correct":true},{"t":"공을 친구 쪽으로 세게 던져요","mis":"SC3-1-u1-X08"},{"t":"페트병을 친구에게 던져요","mis":"SC3-1-u1-X08"},{"t":"페트병 위에 올라가 놀아요","mis":"SC3-1-u1-X08"}],"explanation":["다치지 않아야 해요.","던지면 위험해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
