INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_challenge#6','sci',3,1,'u1','L01','g3_1_sci_u1_L01_challenge','lesson_challenge','SC3-1-u1-C2',3,'ox','auto','공 놀이 기록에서 세게 민 공이 페트병을 더 잘 넘어뜨렸어요.',ARRAY['SC3-1-u1-X03']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C2","difficulty":3,"kind":"ox","stem":"공 놀이 기록에서 세게 민 공이 페트병을 더 잘 넘어뜨렸어요.","answer":"O","reason_options":[{"t":"힘을 세게 줄수록 공이 빠르게 굴러가 페트병에 세게 부딪치기 때문에","correct":true},{"t":"힘의 세기는 놀이 결과와 아무 관계가 없기 때문에","mis":"SC3-1-u1-X03"}],"mis":"SC3-1-u1-X03","explanation":["③을 읽어요.","넘어졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 페트병 두 개를 바닥에 세웠다.","② 공을 약하게 밀었더니 천천히 굴러가다 페트병에 닿지 못했다.","③ 공을 세게 밀었더니 빠르게 굴러가 페트병이 넘어졌다.","④ 찰흙을 손으로 꾹 눌렀더니 납작해졌다."],"title":"공 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
