INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_challenge#8','sci',3,1,'u1','L01','g3_1_sci_u1_L01_challenge','lesson_challenge','SC3-1-u1-C4',4,'mc','auto','친구가 「힘을 받으면 물체는 움직이기만 하고 모양은 절대 변하지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X04','SC3-1-u1-X37']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C4","difficulty":4,"kind":"mc","stem":"친구가 「힘을 받으면 물체는 움직이기만 하고 모양은 절대 변하지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「찰흙을 누르면 납작해지듯이 힘을 받으면 모양이 변하기도 해.」","correct":true},{"t":"「맞아, 모양은 변하지 않아.」","mis":"SC3-1-u1-X04"},{"t":"「힘을 받으면 색깔만 바뀌어.」","mis":"SC3-1-u1-X04"},{"t":"「힘은 눈에 보이니까 쉽게 알 수 있어.」","mis":"SC3-1-u1-X37"}],"explanation":["찰흙을 떠올려요.","모양이 변했어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_challenge#9','sci',3,1,'u1','L01','g3_1_sci_u1_L01_challenge','lesson_challenge','SC3-1-u1-C3',4,'mc','auto','친구가 「밀기는 힘이지만 당기기는 힘이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X01','SC3-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C3","difficulty":4,"kind":"mc","stem":"친구가 「밀기는 힘이지만 당기기는 힘이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「줄을 당겨도 물체가 움직이니 당기기도 힘이야.」","correct":true},{"t":"「맞아, 미는 것만 힘이야.」","mis":"SC3-1-u1-X01"},{"t":"「당기기는 바라보는 거야.」","mis":"SC3-1-u1-X02"},{"t":"「밀기와 당기기는 같은 말이야.」","mis":"SC3-1-u1-X01"}],"explanation":["줄다리기를 떠올려요.","당겨도 움직여요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L01_challenge#10','sci',3,1,'u1','L01','g3_1_sci_u1_L01_challenge','lesson_challenge','SC3-1-u1-C2',4,'essay','teacher','공 놀이 기록을 보고, 멀리 있는 페트병을 넘어뜨리려면 공을 어떻게 밀어야 할지 쓰고 그 까닭을 힘의 세기와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C2","difficulty":4,"kind":"essay","stem":"공 놀이 기록을 보고, 멀리 있는 페트병을 넘어뜨리려면 공을 어떻게 밀어야 할지 쓰고 그 까닭을 힘의 세기와 이어 쓰세요.","answer_guide":{"answer":"예: 공을 더 세게 밀어야 한다. 힘을 세게 줄수록 공이 빠르고 멀리 굴러가서 페트병에 부딪쳐 넘어뜨릴 수 있기 때문이다.","scoring_points":["세게 밀어야 한다고 썼는가","세게 밀수록 멀리 간다는 까닭을 썼는가","공이 페트병에 부딪쳐 힘을 준다고 이었는가"]},"explanation":["②와 ③을 견줘요.","힘의 세기예요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 페트병 두 개를 바닥에 세웠다.","② 공을 약하게 밀었더니 천천히 굴러가다 페트병에 닿지 못했다.","③ 공을 세게 밀었더니 빠르게 굴러가 페트병이 넘어졌다.","④ 찰흙을 손으로 꾹 눌렀더니 납작해졌다."],"title":"공 놀이 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#1','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C8',1,'mc','auto','흔들리는 그네를 멈추게 하려면 어떻게 해야 하나요?',ARRAY['SC3-1-u1-X02','SC3-1-u1-X07']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C8","difficulty":1,"kind":"mc","stem":"흔들리는 그네를 멈추게 하려면 어떻게 해야 하나요?","options":[{"t":"손으로 그네를 잡아 힘을 줘요","correct":true},{"t":"그네를 그냥 바라봐요","mis":"SC3-1-u1-X02"},{"t":"그네 이름을 불러요","mis":"SC3-1-u1-X02"},{"t":"그네를 더 세게 밀어요","mis":"SC3-1-u1-X07"}],"explanation":["손으로 무엇을 하나요?","꽉 잡아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#2','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C9',1,'mc','auto','멈춰 있는 공이 굴러가려면 무엇이 필요한가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C9","difficulty":1,"kind":"mc","stem":"멈춰 있는 공이 굴러가려면 무엇이 필요한가요?","options":[{"t":"공에 힘을 주어야 해요","correct":true},{"t":"아무것도 필요 없어요","mis":"SC3-1-u1-X05"},{"t":"공을 바라보기만 하면 돼요","mis":"SC3-1-u1-X02"},{"t":"공 이름을 부르면 돼요","mis":"SC3-1-u1-X02"}],"explanation":["공은 스스로 못 가요.","밀거나 차요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#3','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C6',1,'ox','auto','그네를 밀거나 손수레를 당기는 것처럼 우리 생활 곳곳에서 힘을 써요.',ARRAY['SC3-1-u1-X38']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C6","difficulty":1,"kind":"ox","stem":"그네를 밀거나 손수레를 당기는 것처럼 우리 생활 곳곳에서 힘을 써요.","answer":"O","reason_options":[{"t":"밀기와 당기기는 생활 곳곳에서 볼 수 있는 힘이기 때문에","correct":true},{"t":"힘은 과학 실험을 할 때만 쓰이기 때문에","mis":"SC3-1-u1-X38"}],"mis":"SC3-1-u1-X38","explanation":["공원을 떠올려요.","여기저기 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#4','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C7',1,'sa','auto','멈춰 있는 수레를 밀면 수레가 어떻게 되나요? 「수레가 ○○○○.」의 ○○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C7","difficulty":1,"kind":"sa","stem":"멈춰 있는 수레를 밀면 수레가 어떻게 되나요? 「수레가 ○○○○.」의 ○○○○에 알맞은 말을 쓰세요.","answer":["움직여요","움직인다","움직여","움직임"],"explanation":["밀면 어떻게 될까요?","앞으로 가요.","「움직여요」예요."],"mis":"SC3-1-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#5','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C7',2,'match','auto','생활 속에서 힘을 준 일과 그 뒤에 일어난 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C7","difficulty":2,"kind":"match","stem":"생활 속에서 힘을 준 일과 그 뒤에 일어난 일을 알맞게 이으세요.","pairs":[{"l":"그네를 밀어요","r":"그네가 앞으로 움직여요"},{"l":"굴러오는 공을 손으로 잡아요","r":"공이 멈춰요"},{"l":"손수레를 당겨요","r":"손수레가 끌려와요"}],"mis":"SC3-1-u1-X07","explanation":["움직였나요, 멈췄나요?","하나씩 따져요.","이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#6','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C10',2,'mc','auto','다음 가운데 힘을 쓰는 일은 무엇인가요?',ARRAY['SC3-1-u1-X02']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C10","difficulty":2,"kind":"mc","stem":"다음 가운데 힘을 쓰는 일은 무엇인가요?","options":[{"t":"닫힌 문을 당겨 열기","correct":true},{"t":"구름 바라보기","mis":"SC3-1-u1-X02"},{"t":"노래 듣기","mis":"SC3-1-u1-X02"},{"t":"눈을 감고 생각하기","mis":"SC3-1-u1-X02"}],"explanation":["물체를 밀거나 당겼나요?","문을 당겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#7','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C9',2,'ox','auto','손으로 미는 휠체어는 아무도 밀지 않아도 스스로 앞으로 가요.',ARRAY['SC3-1-u1-X05']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C9","difficulty":2,"kind":"ox","stem":"손으로 미는 휠체어는 아무도 밀지 않아도 스스로 앞으로 가요.","answer":"X","reason_options":[{"t":"사람이 손으로 밀어 힘을 주어야 앞으로 가기 때문에","correct":true},{"t":"바퀴가 달린 물체는 저절로 움직이기 때문에","mis":"SC3-1-u1-X05"}],"mis":"SC3-1-u1-X05","explanation":["③을 떠올려요.","손으로 밀었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_basic#8','sci',3,1,'u1','L02','g3_1_sci_u1_L02_basic','lesson_basic','SC3-1-u1-C8',2,'mc','auto','공원에서 찾은 힘 ②에서 힘은 어떤 일을 했나요?',ARRAY['SC3-1-u1-X07','SC3-1-u1-X06','SC3-1-u1-X04']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C8","difficulty":2,"kind":"mc","stem":"공원에서 찾은 힘 ②에서 힘은 어떤 일을 했나요?","options":[{"t":"흔들리던 그네를 멈추게 했어요","correct":true},{"t":"그네를 더 빨리 움직이게 했어요","mis":"SC3-1-u1-X07"},{"t":"아무 일도 하지 않았어요","mis":"SC3-1-u1-X06"},{"t":"그네 색깔을 바꾸었어요","mis":"SC3-1-u1-X04"}],"explanation":["②를 읽어요.","꽉 잡았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 아이가 그네를 밀자 그네가 앞으로 움직였다.","② 흔들리던 그네를 손으로 꽉 잡자 그네가 멈췄다.","③ 할머니가 탄 휠체어를 손으로 밀어 앞으로 갔다.","④ 손수레를 당기자 손수레가 끌려왔다.","⑤ 벤치에 앉아 구름을 바라보았다."],"title":"공원에서 찾은 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
