INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_challenge#6','sci',3,1,'u1','L02','g3_1_sci_u1_L02_challenge','lesson_challenge','SC3-1-u1-C6',3,'ox','auto','공원에서 찾은 힘 ①과 ③에는 모두 미는 힘이 쓰였어요.',ARRAY['SC3-1-u1-X05']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C6","difficulty":3,"kind":"ox","stem":"공원에서 찾은 힘 ①과 ③에는 모두 미는 힘이 쓰였어요.","answer":"O","reason_options":[{"t":"그네와 휠체어 모두 손으로 밀어 움직였기 때문에","correct":true},{"t":"휠체어는 스스로 움직였기 때문에","mis":"SC3-1-u1-X05"}],"mis":"SC3-1-u1-X05","explanation":["①과 ③을 읽어요.","둘 다 밀었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 아이가 그네를 밀자 그네가 앞으로 움직였다.","② 흔들리던 그네를 손으로 꽉 잡자 그네가 멈췄다.","③ 할머니가 탄 휠체어를 손으로 밀어 앞으로 갔다.","④ 손수레를 당기자 손수레가 끌려왔다.","⑤ 벤치에 앉아 구름을 바라보았다."],"title":"공원에서 찾은 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_challenge#7','sci',3,1,'u1','L02','g3_1_sci_u1_L02_challenge','lesson_challenge','SC3-1-u1-C9',3,'mc','auto','멈춰 있던 수레가 움직이기 시작했어요. 가장 알맞은 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02','SC3-1-u1-X04']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C9","difficulty":3,"kind":"mc","stem":"멈춰 있던 수레가 움직이기 시작했어요. 가장 알맞은 까닭은 무엇인가요?","options":[{"t":"누군가 수레를 밀거나 당겼기 때문에","correct":true},{"t":"수레가 스스로 움직이고 싶어서","mis":"SC3-1-u1-X05"},{"t":"수레를 오래 바라보아서","mis":"SC3-1-u1-X02"},{"t":"수레 색깔이 바뀌어서","mis":"SC3-1-u1-X04"}],"explanation":["물체는 스스로 못 움직여요.","힘을 받았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_challenge#8','sci',3,1,'u1','L02','g3_1_sci_u1_L02_challenge','lesson_challenge','SC3-1-u1-C9',4,'mc','auto','친구가 「공은 둥글어서 힘을 주지 않아도 스스로 굴러가.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02','SC3-1-u1-X07']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C9","difficulty":4,"kind":"mc","stem":"친구가 「공은 둥글어서 힘을 주지 않아도 스스로 굴러가.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「공도 멈춰 있을 때는 누가 힘을 주어야 굴러가.」","correct":true},{"t":"「맞아, 둥근 물체는 저절로 굴러가.」","mis":"SC3-1-u1-X05"},{"t":"「공은 바라보면 굴러가.」","mis":"SC3-1-u1-X02"},{"t":"「공을 당기면 멈춰 버려.」","mis":"SC3-1-u1-X07"}],"explanation":["멈춰 있는 공을 떠올려요.","차야 굴러가요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_challenge#9','sci',3,1,'u1','L02','g3_1_sci_u1_L02_challenge','lesson_challenge','SC3-1-u1-C8',4,'mc','auto','친구가 「힘은 물체를 움직이게 할 때만 쓰여.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X06','SC3-1-u1-X07','SC3-1-u1-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C8","difficulty":4,"kind":"mc","stem":"친구가 「힘은 물체를 움직이게 할 때만 쓰여.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「흔들리는 그네를 잡아 멈출 때처럼 멈추게 할 때도 힘을 써.」","correct":true},{"t":"「맞아, 멈출 때는 힘이 필요 없어.」","mis":"SC3-1-u1-X06"},{"t":"「멈추게 하려면 더 세게 밀면 돼.」","mis":"SC3-1-u1-X07"},{"t":"「물체는 저절로 멈추고 움직여.」","mis":"SC3-1-u1-X05"}],"explanation":["②를 떠올려요.","잡아서 멈췄어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L02_challenge#10','sci',3,1,'u1','L02','g3_1_sci_u1_L02_challenge','lesson_challenge','SC3-1-u1-C6',4,'essay','teacher','공원에서 찾은 힘 ①~④ 가운데 힘이 물체를 움직이게 한 일과 멈추게 한 일을 하나씩 골라 쓰고, 우리 생활에서 힘을 쓰는 일을 하나 더 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C6","difficulty":4,"kind":"essay","stem":"공원에서 찾은 힘 ①~④ 가운데 힘이 물체를 움직이게 한 일과 멈추게 한 일을 하나씩 골라 쓰고, 우리 생활에서 힘을 쓰는 일을 하나 더 쓰세요.","answer_guide":{"answer":"예: 움직이게 한 일은 ① 그네를 민 일이고, 멈추게 한 일은 ② 흔들리던 그네를 잡은 일이다. 생활에서는 책상을 밀어 옮길 때 힘을 쓴다.","scoring_points":["움직이게 한 일을 골랐는가","멈추게 한 일을 골랐는가","생활 속 힘을 하나 더 썼는가"]},"explanation":["①~④를 읽어요.","움직임과 멈춤이에요.","하나씩 써요."],"asset":{"type":"passage","lines":["① 아이가 그네를 밀자 그네가 앞으로 움직였다.","② 흔들리던 그네를 손으로 꽉 잡자 그네가 멈췄다.","③ 할머니가 탄 휠체어를 손으로 밀어 앞으로 갔다.","④ 손수레를 당기자 손수레가 끌려왔다.","⑤ 벤치에 앉아 구름을 바라보았다."],"title":"공원에서 찾은 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#1','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C11',1,'mc','auto','빈 상자와 물건이 가득 찬 상자를 밀 때 더 큰 힘이 드는 것은 무엇인가요?',ARRAY['SC3-1-u1-X09']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C11","difficulty":1,"kind":"mc","stem":"빈 상자와 물건이 가득 찬 상자를 밀 때 더 큰 힘이 드는 것은 무엇인가요?","options":[{"t":"물건이 가득 찬 상자","correct":true},{"t":"빈 상자","mis":"SC3-1-u1-X09"},{"t":"둘 다 똑같아요","mis":"SC3-1-u1-X09"},{"t":"둘 다 힘이 들지 않아요","mis":"SC3-1-u1-X09"}],"explanation":["어느 쪽이 무거울까요?","가득 찬 상자예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#2','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C13',1,'mc','auto','물체가 무거울수록 밀 때 드는 힘은 어떻게 되나요?',ARRAY['SC3-1-u1-X09']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C13","difficulty":1,"kind":"mc","stem":"물체가 무거울수록 밀 때 드는 힘은 어떻게 되나요?","options":[{"t":"더 커져요","correct":true},{"t":"더 작아져요","mis":"SC3-1-u1-X09"},{"t":"늘 똑같아요","mis":"SC3-1-u1-X09"},{"t":"힘이 사라져요","mis":"SC3-1-u1-X09"}],"explanation":["무거운 상자를 떠올려요.","힘이 많이 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#3','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C12',1,'ox','auto','무거운 수레를 당길 때도 가벼운 수레를 당길 때보다 큰 힘이 들어요.',ARRAY['SC3-1-u1-X10']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C12","difficulty":1,"kind":"ox","stem":"무거운 수레를 당길 때도 가벼운 수레를 당길 때보다 큰 힘이 들어요.","answer":"O","reason_options":[{"t":"당길 때도 물체가 무거울수록 큰 힘이 들기 때문에","correct":true},{"t":"당길 때는 무게와 상관없이 힘이 똑같기 때문에","mis":"SC3-1-u1-X10"}],"mis":"SC3-1-u1-X10","explanation":["당길 때도 생각해요.","밀 때와 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#4','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C11',1,'sa','auto','「무거운 물체를 밀 때는 가벼운 물체를 밀 때보다 (  ) 힘이 들어요.」 빈칸에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C11","difficulty":1,"kind":"sa","stem":"「무거운 물체를 밀 때는 가벼운 물체를 밀 때보다 (  ) 힘이 들어요.」 빈칸에 알맞은 한 글자를 쓰세요.","answer":["큰"],"explanation":["무거운 상자를 떠올려요.","힘이 많이 들어요.","「큰」이에요."],"mis":"SC3-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#5','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C13',2,'match','auto','세 상자 밀기에서 상자와 드는 힘을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C13","difficulty":2,"kind":"match","stem":"세 상자 밀기에서 상자와 드는 힘을 알맞게 이으세요.","pairs":[{"l":"㉠ 빈 상자","r":"가장 작은 힘"},{"l":"㉡ 책 1권 상자","r":"중간 힘"},{"l":"㉢ 책 3권 상자","r":"가장 큰 힘"}],"mis":"SC3-1-u1-X09","explanation":["어느 상자가 가장 무거울까요?","책이 많을수록 무거워요.","하나씩 이어요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자","㉡ 과학책 1권을 넣은 상자","㉢ 과학책 3권을 넣은 상자","드는 힘을 먼저 예상한 뒤 하나씩 밀어 보았다."],"title":"세 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#6','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C15',2,'mc','auto','무거운 상자를 옮길 때 지킬 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X08']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C15","difficulty":2,"kind":"mc","stem":"무거운 상자를 옮길 때 지킬 일로 알맞은 것은 무엇인가요?","options":[{"t":"너무 무거우면 무리해서 들지 않고 친구나 어른과 함께 옮겨요","correct":true},{"t":"혼자 힘껏 번쩍 들어 올려요","mis":"SC3-1-u1-X08"},{"t":"상자를 친구 쪽으로 세게 밀어요","mis":"SC3-1-u1-X08"},{"t":"상자 위에 올라타 밀어요","mis":"SC3-1-u1-X08"}],"explanation":["다치지 않아야 해요.","함께해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#7','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C14',2,'ox','auto','두 상자를 밀기 전에 드는 힘을 예상하고, 직접 밀어 본 뒤 예상과 비교해요.',ARRAY['SC3-1-u1-X11']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C14","difficulty":2,"kind":"ox","stem":"두 상자를 밀기 전에 드는 힘을 예상하고, 직접 밀어 본 뒤 예상과 비교해요.","answer":"O","reason_options":[{"t":"예상한 것과 실제로 느낀 힘을 비교해야 바르게 알 수 있기 때문에","correct":true},{"t":"예상만 하면 직접 밀어 볼 필요가 없기 때문에","mis":"SC3-1-u1-X11"}],"mis":"SC3-1-u1-X11","explanation":["탐구의 차례예요.","예상 → 해 보기 → 비교예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#8','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C13',2,'mc','auto','세 상자 밀기에서 밀 때 큰 힘이 드는 차례대로 놓은 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C13","difficulty":2,"kind":"mc","stem":"세 상자 밀기에서 밀 때 큰 힘이 드는 차례대로 놓은 것은 무엇인가요?","options":[{"t":"㉢ → ㉡ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"SC3-1-u1-X09"},{"t":"㉡ → ㉠ → ㉢","mis":"SC3-1-u1-X09"},{"t":"크기가 같으니 모두 같아요","mis":"SC3-1-u1-X12"}],"explanation":["책이 많은 상자부터예요.","㉢이 가장 무거워요.","첫 번째예요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자","㉡ 과학책 1권을 넣은 상자","㉢ 과학책 3권을 넣은 상자","드는 힘을 먼저 예상한 뒤 하나씩 밀어 보았다."],"title":"세 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#9','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C12',2,'mc','auto','짐을 가득 실은 수레와 빈 수레를 당길 때를 비교한 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X10','SC3-1-u1-X01']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C12","difficulty":2,"kind":"mc","stem":"짐을 가득 실은 수레와 빈 수레를 당길 때를 비교한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"짐을 가득 실은 수레를 당길 때 더 큰 힘이 들어요","correct":true},{"t":"빈 수레를 당길 때 더 큰 힘이 들어요","mis":"SC3-1-u1-X09"},{"t":"당길 때는 둘 다 같은 힘이 들어요","mis":"SC3-1-u1-X10"},{"t":"당기는 것은 힘이 아니에요","mis":"SC3-1-u1-X01"}],"explanation":["어느 수레가 무거울까요?","짐을 실은 수레예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_basic#10','sci',3,1,'u1','L03','g3_1_sci_u1_L03_basic','lesson_basic','SC3-1-u1-C11',3,'mc','auto','책이 반쯤 꽂힌 책장과 빈 책장을 밀 때를 비교한 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C11","difficulty":3,"kind":"mc","stem":"책이 반쯤 꽂힌 책장과 빈 책장을 밀 때를 비교한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"책이 반쯤 꽂힌 책장을 밀 때 더 큰 힘이 들어요","correct":true},{"t":"빈 책장을 밀 때 더 큰 힘이 들어요","mis":"SC3-1-u1-X09"},{"t":"책장은 크기가 같으니 똑같은 힘이 들어요","mis":"SC3-1-u1-X12"},{"t":"책장은 밀어도 힘이 들지 않아요","mis":"SC3-1-u1-X09"}],"explanation":["책이 있으면 무거워요.","무거우면 큰 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#1','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C14',2,'blank','auto','「두 상자를 밀 때 드는 힘을 미리 (      )하고, 직접 밀어 본 뒤 비교해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X11','SC3-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C14","difficulty":2,"kind":"blank","stem":"「두 상자를 밀 때 드는 힘을 미리 (      )하고, 직접 밀어 본 뒤 비교해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"예상","correct":true},{"t":"발표","mis":"SC3-1-u1-X11"},{"t":"구경","mis":"SC3-1-u1-X02"},{"t":"정리","mis":"SC3-1-u1-X11"}],"explanation":["밀기 전에 하는 일이에요.","미리 생각해요.","「예상」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#2','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C12',2,'mc','auto','무거운 물체와 가벼운 물체를 당길 때 드는 힘을 바르게 말한 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X10']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C12","difficulty":2,"kind":"mc","stem":"무거운 물체와 가벼운 물체를 당길 때 드는 힘을 바르게 말한 것은 무엇인가요?","options":[{"t":"무거운 물체를 당길 때 더 큰 힘이 들어요","correct":true},{"t":"가벼운 물체를 당길 때 더 큰 힘이 들어요","mis":"SC3-1-u1-X09"},{"t":"당길 때는 무게와 상관없이 같아요","mis":"SC3-1-u1-X10"},{"t":"당길 때는 힘이 들지 않아요","mis":"SC3-1-u1-X10"}],"explanation":["밀 때와 같아요.","무거우면 큰 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#3','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C13',3,'error','auto','친구들이 상자를 밀어 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u1-X12','SC3-1-u1-X09']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C13","difficulty":3,"kind":"error","stem":"친구들이 상자를 밀어 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「상자는 크기가 클수록 언제나 큰 힘이 들어.」","correct":true,"mis_target":"SC3-1-u1-X12"},{"t":"친구 나 — 「같은 크기라도 책을 많이 넣은 상자가 큰 힘이 들어.」","mis":"SC3-1-u1-X12"},{"t":"친구 다 — 「빈 상자는 작은 힘으로도 움직여.」","mis":"SC3-1-u1-X09"}],"explanation":["크기만 보면 안 돼요.","무거운지를 봐요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#4','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C13',3,'mc','auto','다음 가운데 밀 때 가장 큰 힘이 드는 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C13","difficulty":3,"kind":"mc","stem":"다음 가운데 밀 때 가장 큰 힘이 드는 것은 무엇인가요?","options":[{"t":"벽돌을 가득 실은 수레","correct":true},{"t":"빈 수레","mis":"SC3-1-u1-X09"},{"t":"풍선을 가득 실은 수레","mis":"SC3-1-u1-X12"},{"t":"깃털을 가득 실은 수레","mis":"SC3-1-u1-X12"}],"explanation":["가장 무거운 것을 찾아요.","벽돌이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#5','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C14',3,'mc','auto','상자를 밀어 보는 탐구의 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X11']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C14","difficulty":3,"kind":"mc","stem":"상자를 밀어 보는 탐구의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"드는 힘 예상하기 → 직접 밀어 보기 → 예상과 비교하기","correct":true},{"t":"직접 밀어 보기 → 예상하기 → 끝내기","mis":"SC3-1-u1-X11"},{"t":"예상하기 → 끝내기","mis":"SC3-1-u1-X11"},{"t":"비교하기 → 예상하기 → 밀어 보기","mis":"SC3-1-u1-X11"}],"explanation":["예상이 먼저예요.","해 보고 비교해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#6','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C15',3,'ox','auto','무거운 물체도 힘이 세면 혼자 무리해서 들어도 괜찮아요.',ARRAY['SC3-1-u1-X08']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C15","difficulty":3,"kind":"ox","stem":"무거운 물체도 힘이 세면 혼자 무리해서 들어도 괜찮아요.","answer":"X","reason_options":[{"t":"무리해서 들면 다칠 수 있으니 함께 옮기거나 도움을 받아야 하기 때문에","correct":true},{"t":"힘이 세면 다치지 않기 때문에","mis":"SC3-1-u1-X08"}],"mis":"SC3-1-u1-X08","explanation":["안전을 생각해요.","다칠 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#7','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C11',3,'mc','auto','세 상자 밀기의 ㉡ 상자에 과학책 2권을 더 넣고 밀면 드는 힘은 어떻게 될까요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C11","difficulty":3,"kind":"mc","stem":"세 상자 밀기의 ㉡ 상자에 과학책 2권을 더 넣고 밀면 드는 힘은 어떻게 될까요?","options":[{"t":"처음보다 더 큰 힘이 들어요","correct":true},{"t":"처음보다 작은 힘이 들어요","mis":"SC3-1-u1-X09"},{"t":"상자 크기가 같으니 그대로예요","mis":"SC3-1-u1-X12"},{"t":"힘이 들지 않아요","mis":"SC3-1-u1-X09"}],"explanation":["책을 더 넣었어요.","더 무거워졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자","㉡ 과학책 1권을 넣은 상자","㉢ 과학책 3권을 넣은 상자","드는 힘을 먼저 예상한 뒤 하나씩 밀어 보았다."],"title":"세 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#8','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C11',4,'mc','auto','친구가 「빈 상자도 가득 찬 상자도 크기가 같으니 밀 때 드는 힘이 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X12','SC3-1-u1-X09']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C11","difficulty":4,"kind":"mc","stem":"친구가 「빈 상자도 가득 찬 상자도 크기가 같으니 밀 때 드는 힘이 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「크기가 같아도 가득 찬 상자가 더 무거워서 더 큰 힘이 들어.」","correct":true},{"t":"「맞아, 크기가 같으면 힘도 같아.」","mis":"SC3-1-u1-X12"},{"t":"「빈 상자가 더 큰 힘이 들어.」","mis":"SC3-1-u1-X09"},{"t":"「상자는 밀어도 힘이 안 들어.」","mis":"SC3-1-u1-X09"}],"explanation":["크기와 무게는 달라요.","무거운 쪽이 큰 힘이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#9','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C12',4,'mc','auto','친구가 「밀 때는 무게가 중요하지만, 당길 때는 무게와 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X10','SC3-1-u1-X09','SC3-1-u1-X01']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C12","difficulty":4,"kind":"mc","stem":"친구가 「밀 때는 무게가 중요하지만, 당길 때는 무게와 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「당길 때도 무거운 물체일수록 큰 힘이 들어.」","correct":true},{"t":"「맞아, 당길 때는 상관없어.」","mis":"SC3-1-u1-X10"},{"t":"「당길 때는 가벼울수록 큰 힘이 들어.」","mis":"SC3-1-u1-X09"},{"t":"「당기는 건 힘이 아니야.」","mis":"SC3-1-u1-X01"}],"explanation":["수레를 당겨 봐요.","짐이 많으면 힘들어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L03_challenge#10','sci',3,1,'u1','L03','g3_1_sci_u1_L03_challenge','lesson_challenge','SC3-1-u1-C13',4,'essay','teacher','세 상자 밀기에서 밀 때 큰 힘이 드는 차례를 쓰고, 그렇게 생각한 까닭을 무게와 힘을 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C13","difficulty":4,"kind":"essay","stem":"세 상자 밀기에서 밀 때 큰 힘이 드는 차례를 쓰고, 그렇게 생각한 까닭을 무게와 힘을 이어 쓰세요.","answer_guide":{"answer":"예: ㉢, ㉡, ㉠ 차례로 큰 힘이 든다. 세 상자는 크기가 같지만 책을 많이 넣을수록 무겁고, 물체가 무거울수록 밀 때 큰 힘이 들기 때문이다.","scoring_points":["㉢ → ㉡ → ㉠ 차례를 썼는가","책이 많을수록 무겁다고 썼는가","무거울수록 큰 힘이 든다고 이었는가"]},"explanation":["책의 수를 봐요.","무거울수록 큰 힘이에요.","까닭을 써요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자","㉡ 과학책 1권을 넣은 상자","㉢ 과학책 3권을 넣은 상자","드는 힘을 먼저 예상한 뒤 하나씩 밀어 보았다."],"title":"세 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#1','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C20',1,'mc','auto','수평대가 왼쪽으로 기울었어요. 어느 쪽 물체가 더 무거운가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X16']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C20","difficulty":1,"kind":"mc","stem":"수평대가 왼쪽으로 기울었어요. 어느 쪽 물체가 더 무거운가요?","options":[{"t":"왼쪽 물체","correct":true},{"t":"오른쪽 물체","mis":"SC3-1-u1-X13"},{"t":"두 물체의 무게가 같아요","mis":"SC3-1-u1-X16"},{"t":"알 수 없어요","mis":"SC3-1-u1-X13"}],"explanation":["아래로 내려간 쪽이에요.","왼쪽이 내려갔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#2','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C17',1,'mc','auto','어느 쪽으로도 기울어지지 않은 상태를 무엇이라고 하나요?',ARRAY['SC3-1-u1-X15']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C17","difficulty":1,"kind":"mc","stem":"어느 쪽으로도 기울어지지 않은 상태를 무엇이라고 하나요?","options":[{"t":"수평","correct":true},{"t":"무게","mis":"SC3-1-u1-X15"},{"t":"기울기","mis":"SC3-1-u1-X15"},{"t":"높이","mis":"SC3-1-u1-X15"}],"explanation":["오늘 배운 낱말이에요.","평평해요.","수평이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#3','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C19',1,'ox','auto','무게가 같은 두 물체를 같은 거리에 올리면 수평을 이뤄요.',ARRAY['SC3-1-u1-X16']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C19","difficulty":1,"kind":"ox","stem":"무게가 같은 두 물체를 같은 거리에 올리면 수평을 이뤄요.","answer":"O","reason_options":[{"t":"무게가 같으면 어느 쪽으로도 기울지 않기 때문에","correct":true},{"t":"두 물체를 올리면 언제나 한쪽으로 기울기 때문에","mis":"SC3-1-u1-X16"}],"mis":"SC3-1-u1-X16","explanation":["①을 떠올려요.","같은 나무토막이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#4','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C16',1,'sa','auto','물체의 무겁고 가벼운 정도를 무엇이라고 하나요?','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C16","difficulty":1,"kind":"sa","stem":"물체의 무겁고 가벼운 정도를 무엇이라고 하나요?","answer":["무게"],"explanation":["두 글자예요.","무겁고 가벼운 정도예요.","무게예요."],"mis":"SC3-1-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#5','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C19',2,'match','auto','수평대의 모습과 알 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C19","difficulty":2,"kind":"match","stem":"수평대의 모습과 알 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"수평을 이뤄요","r":"두 물체의 무게가 같아요"},{"l":"왼쪽으로 기울어요","r":"왼쪽 물체가 더 무거워요"},{"l":"오른쪽으로 기울어요","r":"오른쪽 물체가 더 무거워요"}],"mis":"SC3-1-u1-X13","explanation":["기운 쪽을 봐요.","내려간 쪽이 무거워요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#6','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C18',2,'mc','auto','수평 잡기로 무게를 비교할 때 물체를 놓는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X14']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C18","difficulty":2,"kind":"mc","stem":"수평 잡기로 무게를 비교할 때 물체를 놓는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"받침점에서 양쪽으로 같은 거리에 놓아요","correct":true},{"t":"무거워 보이는 것을 더 멀리 놓아요","mis":"SC3-1-u1-X14"},{"t":"아무 곳에나 놓아요","mis":"SC3-1-u1-X14"},{"t":"한쪽 끝에 모두 놓아요","mis":"SC3-1-u1-X14"}],"explanation":["거리를 맞춰요.","양쪽이 같아야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#7','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C20',2,'ox','auto','수평 잡기 활동 ②에서 자는 나무토막 2개를 올린 오른쪽으로 기울어요.',ARRAY['SC3-1-u1-X13']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C20","difficulty":2,"kind":"ox","stem":"수평 잡기 활동 ②에서 자는 나무토막 2개를 올린 오른쪽으로 기울어요.","answer":"O","reason_options":[{"t":"나무토막 2개가 1개보다 무거워 무거운 쪽으로 기울기 때문에","correct":true},{"t":"수평대는 가벼운 쪽으로 기울기 때문에","mis":"SC3-1-u1-X13"}],"mis":"SC3-1-u1-X13","explanation":["②를 읽어요.","2개가 더 무거워요.","그래서 O예요."],"asset":{"type":"passage","lines":["휴지 심 위에 자를 올려 수평을 이루게 했다.","① 같은 나무토막을 양 끝에 하나씩 올렸다.","② 왼쪽에 나무토막 1개, 오른쪽에 2개를 올렸다.","③ 지우개 ㉮는 왼쪽, ㉯는 오른쪽 같은 거리에 올렸다.","③에서 자는 오른쪽으로 기울었다."],"title":"수평 잡기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#8','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C22',2,'mc','auto','수평을 이룬 시소의 왼쪽에 친구 한 명이 더 앉으면 시소는 어떻게 될까요?',ARRAY['SC3-1-u1-X18']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C22","difficulty":2,"kind":"mc","stem":"수평을 이룬 시소의 왼쪽에 친구 한 명이 더 앉으면 시소는 어떻게 될까요?","options":[{"t":"왼쪽으로 기울어요","correct":true},{"t":"오른쪽으로 기울어요","mis":"SC3-1-u1-X18"},{"t":"그대로 수평이에요","mis":"SC3-1-u1-X18"},{"t":"시소가 빙글빙글 돌아요","mis":"SC3-1-u1-X18"}],"explanation":["왼쪽이 무거워져요.","무거운 쪽으로 기울어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#9','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C20',2,'mc','auto','수평 잡기 활동 ③에서 더 무거운 지우개는 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X16']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C20","difficulty":2,"kind":"mc","stem":"수평 잡기 활동 ③에서 더 무거운 지우개는 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"SC3-1-u1-X13"},{"t":"둘 다 같아요","mis":"SC3-1-u1-X16"},{"t":"알 수 없어요","mis":"SC3-1-u1-X13"}],"explanation":["마지막 줄을 읽어요.","오른쪽으로 기울었어요.","㉯예요."],"asset":{"type":"passage","lines":["휴지 심 위에 자를 올려 수평을 이루게 했다.","① 같은 나무토막을 양 끝에 하나씩 올렸다.","② 왼쪽에 나무토막 1개, 오른쪽에 2개를 올렸다.","③ 지우개 ㉮는 왼쪽, ㉯는 오른쪽 같은 거리에 올렸다.","③에서 자는 오른쪽으로 기울었다."],"title":"수평 잡기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_basic#10','sci',3,1,'u1','L04','g3_1_sci_u1_L04_basic','lesson_basic','SC3-1-u1-C21',3,'mc','auto','사과, 배, 귤의 무게를 수평 잡기로 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X17','SC3-1-u1-X12']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C21","difficulty":3,"kind":"mc","stem":"사과, 배, 귤의 무게를 수평 잡기로 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두 개씩 차례대로 올려 비교해요","correct":true},{"t":"세 개를 한쪽에 모두 올려요","mis":"SC3-1-u1-X17"},{"t":"크기만 보고 정해요","mis":"SC3-1-u1-X12"},{"t":"색깔이 진한 것이 무겁다고 정해요","mis":"SC3-1-u1-X17"}],"explanation":["한 번에 둘씩이에요.","차례로 견줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#1','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C20',2,'blank','auto','「무게가 다른 두 물체를 같은 거리에 올리면 (      ) 쪽으로 기울어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X12','SC3-1-u1-X17']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C20","difficulty":2,"kind":"blank","stem":"「무게가 다른 두 물체를 같은 거리에 올리면 (      ) 쪽으로 기울어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"더 무거운","correct":true},{"t":"더 가벼운","mis":"SC3-1-u1-X13"},{"t":"더 큰","mis":"SC3-1-u1-X12"},{"t":"색이 진한","mis":"SC3-1-u1-X17"}],"explanation":["②를 떠올려요.","2개 쪽이었어요.","「더 무거운」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#2','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C20',2,'mc','auto','시소가 한쪽으로 기울었을 때 더 무거운 사람은 누구인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X12','SC3-1-u1-X16']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C20","difficulty":2,"kind":"mc","stem":"시소가 한쪽으로 기울었을 때 더 무거운 사람은 누구인가요?","options":[{"t":"아래로 내려간 쪽에 앉은 사람","correct":true},{"t":"위로 올라간 쪽에 앉은 사람","mis":"SC3-1-u1-X13"},{"t":"키가 더 큰 사람","mis":"SC3-1-u1-X12"},{"t":"두 사람 모두 같아요","mis":"SC3-1-u1-X16"}],"explanation":["무거운 쪽으로 기울어요.","내려간 쪽이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#3','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C18',3,'error','auto','친구들이 수평 잡기 활동을 했어요. 잘못한 친구는 누구인가요?',ARRAY['SC3-1-u1-X14','SC3-1-u1-X15']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C18","difficulty":3,"kind":"error","stem":"친구들이 수평 잡기 활동을 했어요. 잘못한 친구는 누구인가요?","options":[{"t":"친구 다 — 「지우개 하나는 자 끝에, 하나는 가운데 가까이 올렸어.」","correct":true,"mis_target":"SC3-1-u1-X14"},{"t":"친구 가 — 「두 지우개를 받침점에서 같은 거리에 올렸어.」","mis":"SC3-1-u1-X14"},{"t":"친구 나 — 「먼저 빈 자가 수평을 이루게 했어.」","mis":"SC3-1-u1-X15"}],"explanation":["거리를 봐요.","같은 거리가 아니에요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#4','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C21',3,'mc','auto','사과와 배를 비교했더니 사과 쪽으로, 사과와 귤을 비교했더니 사과 쪽으로 기울었어요. 가장 무거운 과일은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X17']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C21","difficulty":3,"kind":"mc","stem":"사과와 배를 비교했더니 사과 쪽으로, 사과와 귤을 비교했더니 사과 쪽으로 기울었어요. 가장 무거운 과일은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"배","mis":"SC3-1-u1-X13"},{"t":"귤","mis":"SC3-1-u1-X13"},{"t":"알 수 없어요","mis":"SC3-1-u1-X17"}],"explanation":["두 번 모두 어느 쪽이었나요?","사과 쪽이에요.","사과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#5','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C16',3,'mc','auto','크기가 큰 스펀지 공과 크기가 작은 쇠구슬을 같은 거리에 올렸더니 쇠구슬 쪽으로 기울었어요. 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u1-X12','SC3-1-u1-X16','SC3-1-u1-X13']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C16","difficulty":3,"kind":"mc","stem":"크기가 큰 스펀지 공과 크기가 작은 쇠구슬을 같은 거리에 올렸더니 쇠구슬 쪽으로 기울었어요. 알 수 있는 것은 무엇인가요?","options":[{"t":"크기가 작아도 쇠구슬이 더 무거워요","correct":true},{"t":"크기가 큰 스펀지 공이 더 무거워요","mis":"SC3-1-u1-X12"},{"t":"두 물체의 무게가 같아요","mis":"SC3-1-u1-X16"},{"t":"수평대는 가벼운 쪽으로 기울어요","mis":"SC3-1-u1-X13"}],"explanation":["기운 쪽을 봐요.","크기와 무게는 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#6','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C19',3,'ox','auto','수평 잡기 활동 ①에서 자는 수평을 이뤄요.',ARRAY['SC3-1-u1-X16']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C19","difficulty":3,"kind":"ox","stem":"수평 잡기 활동 ①에서 자는 수평을 이뤄요.","answer":"O","reason_options":[{"t":"같은 나무토막이라 무게가 같기 때문에","correct":true},{"t":"양쪽에 물체를 올리면 언제나 기울기 때문에","mis":"SC3-1-u1-X16"}],"mis":"SC3-1-u1-X16","explanation":["①을 읽어요.","같은 나무토막이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["휴지 심 위에 자를 올려 수평을 이루게 했다.","① 같은 나무토막을 양 끝에 하나씩 올렸다.","② 왼쪽에 나무토막 1개, 오른쪽에 2개를 올렸다.","③ 지우개 ㉮는 왼쪽, ㉯는 오른쪽 같은 거리에 올렸다.","③에서 자는 오른쪽으로 기울었다."],"title":"수평 잡기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#7','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C17',3,'mc','auto','수평 잡기 활동을 하기 전에 먼저 해야 할 일은 무엇인가요?',ARRAY['SC3-1-u1-X15','SC3-1-u1-X14','SC3-1-u1-X08']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C17","difficulty":3,"kind":"mc","stem":"수평 잡기 활동을 하기 전에 먼저 해야 할 일은 무엇인가요?","options":[{"t":"아무것도 올리지 않은 자가 수평을 이루게 해요","correct":true},{"t":"자를 한쪽으로 기울여 놓아요","mis":"SC3-1-u1-X15"},{"t":"무거운 물체부터 아무 곳에 올려요","mis":"SC3-1-u1-X14"},{"t":"자로 친구와 칼싸움을 해요","mis":"SC3-1-u1-X08"}],"explanation":["첫 줄을 읽어요.","수평부터 맞춰요.","첫 번째예요."],"asset":{"type":"passage","lines":["휴지 심 위에 자를 올려 수평을 이루게 했다.","① 같은 나무토막을 양 끝에 하나씩 올렸다.","② 왼쪽에 나무토막 1개, 오른쪽에 2개를 올렸다.","③ 지우개 ㉮는 왼쪽, ㉯는 오른쪽 같은 거리에 올렸다.","③에서 자는 오른쪽으로 기울었다."],"title":"수평 잡기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#8','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C22',4,'mc','auto','친구가 「수평인 시소에 한 명이 더 앉으면 반대쪽으로 기울어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X18','SC3-1-u1-X13']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C22","difficulty":4,"kind":"mc","stem":"친구가 「수평인 시소에 한 명이 더 앉으면 반대쪽으로 기울어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「한 명이 더 앉은 쪽이 무거워지니 그쪽으로 기울어.」","correct":true},{"t":"「맞아, 반대쪽으로 기울어.」","mis":"SC3-1-u1-X18"},{"t":"「사람이 더 앉아도 그대로 수평이야.」","mis":"SC3-1-u1-X18"},{"t":"「시소는 가벼운 쪽으로 기울어.」","mis":"SC3-1-u1-X13"}],"explanation":["어느 쪽이 무거워졌나요?","더 앉은 쪽이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#9','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C18',4,'mc','auto','친구가 「무게를 비교할 때 한 물체는 자 끝에, 한 물체는 가운데에 놓아도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X14','SC3-1-u1-X12']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C18","difficulty":4,"kind":"mc","stem":"친구가 「무게를 비교할 때 한 물체는 자 끝에, 한 물체는 가운데에 놓아도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「받침점에서 같은 거리에 놓아야 무게를 바르게 비교할 수 있어.」","correct":true},{"t":"「맞아, 어디에 놓아도 같아.」","mis":"SC3-1-u1-X14"},{"t":"「무거운 것은 늘 끝에 놓아야 해.」","mis":"SC3-1-u1-X14"},{"t":"「크기만 보고 정하면 돼.」","mis":"SC3-1-u1-X12"}],"explanation":["규칙을 떠올려요.","같은 거리예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L04_challenge#10','sci',3,1,'u1','L04','g3_1_sci_u1_L04_challenge','lesson_challenge','SC3-1-u1-C21',4,'essay','teacher','연필, 풀, 가위 가운데 가장 무거운 것을 수평 잡기로 찾으려고 해요. 어떻게 비교할지 차례대로 쓰고, 물체를 놓을 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C21","difficulty":4,"kind":"essay","stem":"연필, 풀, 가위 가운데 가장 무거운 것을 수평 잡기로 찾으려고 해요. 어떻게 비교할지 차례대로 쓰고, 물체를 놓을 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 먼저 연필과 풀을 올려 더 무거운 쪽을 찾고, 그 물체와 가위를 다시 올려 비교한다. 두 번 모두 기운 쪽의 물체가 가장 무겁다. 물체는 받침점에서 양쪽으로 같은 거리에 놓아야 한다.","scoring_points":["두 개씩 차례로 비교한다고 썼는가","기운 쪽이 더 무겁다고 썼는가","같은 거리에 놓는다고 썼는가"]},"explanation":["한 번에 둘씩이에요.","기운 쪽을 봐요.","차례를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#1','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C24',1,'mc','auto','물체의 무게를 정확하게 비교하려면 어떻게 해야 하나요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X12']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C24","difficulty":1,"kind":"mc","stem":"물체의 무게를 정확하게 비교하려면 어떻게 해야 하나요?","options":[{"t":"저울을 사용해요","correct":true},{"t":"손으로 들어 봐요","mis":"SC3-1-u1-X19"},{"t":"눈으로 보고 짐작해요","mis":"SC3-1-u1-X19"},{"t":"크기만 비교해요","mis":"SC3-1-u1-X12"}],"explanation":["정확한 방법이에요.","숫자로 알려 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#2','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C25',1,'mc','auto','무게의 단위로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X21']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C25","difficulty":1,"kind":"mc","stem":"무게의 단위로 알맞은 것은 무엇인가요?","options":[{"t":"g(그램), kg(킬로그램)","correct":true},{"t":"cm(센티미터)","mis":"SC3-1-u1-X21"},{"t":"L(리터)","mis":"SC3-1-u1-X21"},{"t":"분","mis":"SC3-1-u1-X21"}],"explanation":["무게를 나타내요.","그램이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#3','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C23',1,'ox','auto','손으로 들어서 무게를 비교하면 사람마다 결과가 다를 수 있어요.',ARRAY['SC3-1-u1-X19']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C23","difficulty":1,"kind":"ox","stem":"손으로 들어서 무게를 비교하면 사람마다 결과가 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 무게를 느끼는 느낌이 다르기 때문에","correct":true},{"t":"손은 저울보다 정확하기 때문에","mis":"SC3-1-u1-X19"}],"mis":"SC3-1-u1-X19","explanation":["모둠 친구들을 떠올려요.","차례가 달랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#4','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C25',1,'sa','auto','「300 g」을 소리 내어 읽어 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C25","difficulty":1,"kind":"sa","stem":"「300 g」을 소리 내어 읽어 쓰세요.","answer":["삼백 그램","삼백그램"],"explanation":["g은 그램이에요.","300은 삼백이에요.","삼백 그램이에요."],"mis":"SC3-1-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#5','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C26',2,'match','auto','무게를 비교하는 방법과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C26","difficulty":2,"kind":"match","stem":"무게를 비교하는 방법과 특징을 알맞게 이으세요.","pairs":[{"l":"용수철저울","r":"용수철이 늘어난 눈금을 읽어요"},{"l":"전자저울","r":"무게가 숫자로 나타나요"},{"l":"손으로 들어 보기","r":"사람마다 느낌이 달라요"}],"mis":"SC3-1-u1-X22","explanation":["저울마다 달라요.","눈금과 숫자예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#6','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C28',2,'mc','auto','저울을 쓰는 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X24']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C28","difficulty":2,"kind":"mc","stem":"저울을 쓰는 일로 알맞은 것은 무엇인가요?","options":[{"t":"채소의 무게를 재어 값을 정해요","correct":true},{"t":"텔레비전 소리를 키워요","mis":"SC3-1-u1-X24"},{"t":"교실 온도를 재요","mis":"SC3-1-u1-X24"},{"t":"책상 길이를 재요","mis":"SC3-1-u1-X24"}],"explanation":["무게를 재는 일이에요.","가게를 떠올려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#7','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C26',2,'ox','auto','용수철저울은 세게 잡아당기며 놀아도 괜찮아요.',ARRAY['SC3-1-u1-X23']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C26","difficulty":2,"kind":"ox","stem":"용수철저울은 세게 잡아당기며 놀아도 괜찮아요.","answer":"X","reason_options":[{"t":"세게 당기면 용수철이 늘어나 고장 날 수 있기 때문에","correct":true},{"t":"용수철은 아무리 당겨도 망가지지 않기 때문에","mis":"SC3-1-u1-X23"}],"mis":"SC3-1-u1-X23","explanation":["조심할 점이에요.","고장 날 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#8','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C24',2,'mc','auto','손과 저울 기록에서 가장 무거운 물체는 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X20']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C24","difficulty":2,"kind":"mc","stem":"손과 저울 기록에서 가장 무거운 물체는 무엇인가요?","options":[{"t":"가위","correct":true},{"t":"풀","mis":"SC3-1-u1-X19"},{"t":"지우개","mis":"SC3-1-u1-X19"},{"t":"친구마다 달라서 알 수 없어요","mis":"SC3-1-u1-X20"}],"explanation":["저울 숫자를 봐요.","30 g이 가장 커요.","가위예요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 가위, 풀, 지우개를 손으로 들어 보았다.","친구마다 정한 무거운 차례가 서로 달랐다.","전자저울로 재었더니 가위 30 g, 풀 25 g, 지우개 20 g이었다."],"title":"손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#9','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C23',2,'mc','auto','손과 저울 기록에서 친구마다 손으로 정한 차례가 달랐던 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X20']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C23","difficulty":2,"kind":"mc","stem":"손과 저울 기록에서 친구마다 손으로 정한 차례가 달랐던 까닭은 무엇인가요?","options":[{"t":"사람마다 무게를 느끼는 느낌이 달라서","correct":true},{"t":"물체가 들 때마다 무거워져서","mis":"SC3-1-u1-X19"},{"t":"손이 저울보다 정확해서","mis":"SC3-1-u1-X19"},{"t":"저울이 고장 나서","mis":"SC3-1-u1-X20"}],"explanation":["손 느낌을 떠올려요.","사람마다 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 가위, 풀, 지우개를 손으로 들어 보았다.","친구마다 정한 무거운 차례가 서로 달랐다.","전자저울로 재었더니 가위 30 g, 풀 25 g, 지우개 20 g이었다."],"title":"손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_basic#10','sci',3,1,'u1','L05','g3_1_sci_u1_L05_basic','lesson_basic','SC3-1-u1-C25',3,'mc','auto','다음 가운데 100 g보다 무거운 것은 무엇인가요?',ARRAY['SC3-1-u1-X21']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C25","difficulty":3,"kind":"mc","stem":"다음 가운데 100 g보다 무거운 것은 무엇인가요?","options":[{"t":"수박 3000 g","correct":true},{"t":"동전 5 g","mis":"SC3-1-u1-X21"},{"t":"연필 10 g","mis":"SC3-1-u1-X21"},{"t":"지우개 20 g","mis":"SC3-1-u1-X21"}],"explanation":["숫자를 견줘요.","100보다 큰 수예요.","수박이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#1','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C27',2,'blank','auto','「물체를 올리면 무게가 숫자로 나타나는 것: (      )」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X22','SC3-1-u1-X19']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C27","difficulty":2,"kind":"blank","stem":"「물체를 올리면 무게가 숫자로 나타나는 것: (      )」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전자저울","correct":true},{"t":"용수철저울","mis":"SC3-1-u1-X22"},{"t":"수평대","mis":"SC3-1-u1-X22"},{"t":"손 어림","mis":"SC3-1-u1-X19"}],"explanation":["숫자 화면이 있어요.","전기를 써요.","전자저울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#2','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C28',2,'mc','auto','태권도 경기에서 몸무게에 따라 체급을 정확히 나누려면 어떻게 해야 하나요?',ARRAY['SC3-1-u1-X12','SC3-1-u1-X19']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C28","difficulty":2,"kind":"mc","stem":"태권도 경기에서 몸무게에 따라 체급을 정확히 나누려면 어떻게 해야 하나요?","options":[{"t":"저울로 몸무게를 재어 비교해요","correct":true},{"t":"키를 보고 나눠요","mis":"SC3-1-u1-X12"},{"t":"손으로 서로 들어 보고 나눠요","mis":"SC3-1-u1-X19"},{"t":"눈으로 보고 짐작해요","mis":"SC3-1-u1-X19"}],"explanation":["정확해야 해요.","저울이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#3','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C23',3,'error','auto','친구들이 무게를 비교하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X22','SC3-1-u1-X20']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C23","difficulty":3,"kind":"error","stem":"친구들이 무게를 비교하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「손으로 들어 보면 누구나 똑같이 정확하게 알 수 있어.」","correct":true,"mis_target":"SC3-1-u1-X19"},{"t":"친구 가 — 「전자저울을 쓰면 무게가 숫자로 나와.」","mis":"SC3-1-u1-X22"},{"t":"친구 다 — 「저울을 쓰면 무게를 정확하게 비교할 수 있어.」","mis":"SC3-1-u1-X20"}],"explanation":["손 느낌을 떠올려요.","사람마다 달라요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#4','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C26',3,'mc','auto','용수철저울에 더 무거운 물체를 걸면 어떻게 되나요?',ARRAY['SC3-1-u1-X23','SC3-1-u1-X22']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C26","difficulty":3,"kind":"mc","stem":"용수철저울에 더 무거운 물체를 걸면 어떻게 되나요?","options":[{"t":"용수철이 더 많이 늘어나요","correct":true},{"t":"용수철이 더 짧아져요","mis":"SC3-1-u1-X23"},{"t":"용수철이 그대로예요","mis":"SC3-1-u1-X23"},{"t":"숫자 화면이 켜져요","mis":"SC3-1-u1-X22"}],"explanation":["무거울수록 당기는 힘이 커요.","많이 늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
