INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#6','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C25',3,'ox','auto','요리할 때 「밀가루 200 g」은 「밀가루 이백 그램」이라고 읽어요.',ARRAY['SC3-1-u1-X21']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C25","difficulty":3,"kind":"ox","stem":"요리할 때 「밀가루 200 g」은 「밀가루 이백 그램」이라고 읽어요.","answer":"O","reason_options":[{"t":"g은 무게의 단위 그램이기 때문에","correct":true},{"t":"g은 길이의 단위이기 때문에","mis":"SC3-1-u1-X21"}],"mis":"SC3-1-u1-X21","explanation":["g을 떠올려요.","그램이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#7','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C24',3,'mc','auto','젤리 두 개의 무게가 아주 비슷할 때 무게를 비교하는 가장 좋은 방법은 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X12','SC3-1-u1-X20']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C24","difficulty":3,"kind":"mc","stem":"젤리 두 개의 무게가 아주 비슷할 때 무게를 비교하는 가장 좋은 방법은 무엇인가요?","options":[{"t":"전자저울로 하나씩 재어 숫자를 비교해요","correct":true},{"t":"손으로 번갈아 들어 봐요","mis":"SC3-1-u1-X19"},{"t":"크기가 큰 것을 무겁다고 해요","mis":"SC3-1-u1-X12"},{"t":"저울도 사람마다 다르니 아무렇게나 정해요","mis":"SC3-1-u1-X20"}],"explanation":["아주 비슷하면 손으로는 어려워요.","숫자로 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#8','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C23',4,'mc','auto','친구가 「내가 손으로 들어 보니 필통이 더 무거웠으니까 그게 틀림없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X20']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C23","difficulty":4,"kind":"mc","stem":"친구가 「내가 손으로 들어 보니 필통이 더 무거웠으니까 그게 틀림없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「손 느낌은 사람마다 달라서 저울로 재어 확인해 보자.」","correct":true},{"t":"「맞아, 손이 저울보다 정확해.」","mis":"SC3-1-u1-X19"},{"t":"「눈으로 보고 정하면 돼.」","mis":"SC3-1-u1-X19"},{"t":"「저울도 사람마다 숫자가 달라.」","mis":"SC3-1-u1-X20"}],"explanation":["손 느낌은 어림이에요.","저울로 확인해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#9','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C27',4,'mc','auto','친구가 「전자저울과 용수철저울은 둘 다 용수철이 늘어난 눈금을 읽어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X22','SC3-1-u1-X21']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C27","difficulty":4,"kind":"mc","stem":"친구가 「전자저울과 용수철저울은 둘 다 용수철이 늘어난 눈금을 읽어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「용수철저울은 눈금을 읽고, 전자저울은 숫자로 나타나.」","correct":true},{"t":"「맞아, 둘 다 눈금을 읽어.」","mis":"SC3-1-u1-X22"},{"t":"「둘 다 숫자로만 나타나.」","mis":"SC3-1-u1-X22"},{"t":"「저울은 길이를 재는 기구야.」","mis":"SC3-1-u1-X21"}],"explanation":["두 저울을 견줘요.","눈금과 숫자예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L05_challenge#10','sci',3,1,'u1','L05','g3_1_sci_u1_L05_challenge','lesson_challenge','SC3-1-u1-C24',4,'essay','teacher','손과 저울 기록을 보고, 손으로 들어 비교할 때와 저울을 쓸 때의 다른 점을 쓰고 무게를 비교할 때 저울을 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C24","difficulty":4,"kind":"essay","stem":"손과 저울 기록을 보고, 손으로 들어 비교할 때와 저울을 쓸 때의 다른 점을 쓰고 무게를 비교할 때 저울을 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 손으로 들었을 때는 친구마다 무거운 차례가 달랐지만, 전자저울로 재니 가위 30 g, 풀 25 g, 지우개 20 g으로 정확한 무게를 알 수 있었다. 손 느낌은 사람마다 달라 정확하지 않으므로 무게를 비교할 때는 저울을 써야 한다.","scoring_points":["손으로 들면 사람마다 다르다고 썼는가","저울로 정확한 무게를 알았다고 썼는가","저울을 써야 하는 까닭을 썼는가"]},"explanation":["기록 두 줄을 견줘요.","손과 저울이에요.","까닭을 써요."],"asset":{"type":"passage","lines":["모둠 친구 넷이 가위, 풀, 지우개를 손으로 들어 보았다.","친구마다 정한 무거운 차례가 서로 달랐다.","전자저울로 재었더니 가위 30 g, 풀 25 g, 지우개 20 g이었다."],"title":"손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#1','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C31',1,'mc','auto','지레나 빗면 같은 도구를 쓰면 물체를 들어 올릴 때 드는 힘은 어떻게 되나요?',ARRAY['SC3-1-u1-X25']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C31","difficulty":1,"kind":"mc","stem":"지레나 빗면 같은 도구를 쓰면 물체를 들어 올릴 때 드는 힘은 어떻게 되나요?","options":[{"t":"작은 힘이 들어요","correct":true},{"t":"더 큰 힘이 들어요","mis":"SC3-1-u1-X25"},{"t":"힘이 똑같아요","mis":"SC3-1-u1-X25"},{"t":"힘이 두 배로 들어요","mis":"SC3-1-u1-X25"}],"explanation":["도구는 도와줘요.","힘이 줄어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#2','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C30',1,'mc','auto','비스듬한 면을 무엇이라고 하나요?',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C30","difficulty":1,"kind":"mc","stem":"비스듬한 면을 무엇이라고 하나요?","options":[{"t":"빗면","correct":true},{"t":"지레","mis":"SC3-1-u1-X26"},{"t":"수평","mis":"SC3-1-u1-X26"},{"t":"저울","mis":"SC3-1-u1-X26"}],"explanation":["비스듬하다는 말과 닮았어요.","두 글자예요.","빗면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#3','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C29',1,'ox','auto','막대의 한 점을 받치고 물체를 움직이게 하는 도구를 지레라고 해요.',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C29","difficulty":1,"kind":"ox","stem":"막대의 한 점을 받치고 물체를 움직이게 하는 도구를 지레라고 해요.","answer":"O","reason_options":[{"t":"막대를 받쳐 물체를 움직이게 하는 도구가 지레이기 때문에","correct":true},{"t":"비스듬한 면을 지레라고 하기 때문에","mis":"SC3-1-u1-X26"}],"mis":"SC3-1-u1-X26","explanation":["막대를 떠올려요.","받쳐서 들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#4','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C32',1,'sa','auto','계단과 미끄럼틀은 지레와 빗면 가운데 무엇을 이용한 것인가요?','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C32","difficulty":1,"kind":"sa","stem":"계단과 미끄럼틀은 지레와 빗면 가운데 무엇을 이용한 것인가요?","answer":["빗면"],"explanation":["비스듬한가요?","네, 비스듬해요.","빗면이에요."],"mis":"SC3-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#5','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C32',2,'match','auto','도구와 이용한 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C32","difficulty":2,"kind":"match","stem":"도구와 이용한 것을 알맞게 이으세요.","pairs":[{"l":"가위","r":"지레를 이용해요"},{"l":"경사로","r":"빗면을 이용해요"},{"l":"맨손으로 들기","r":"도구를 쓰지 않아요"}],"mis":"SC3-1-u1-X27","explanation":["막대인가요, 비스듬한 면인가요?","하나씩 따져요.","이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#6','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C32',2,'mc','auto','다음 가운데 지레를 이용한 도구는 무엇인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C32","difficulty":2,"kind":"mc","stem":"다음 가운데 지레를 이용한 도구는 무엇인가요?","options":[{"t":"병따개","correct":true},{"t":"계단","mis":"SC3-1-u1-X27"},{"t":"미끄럼틀","mis":"SC3-1-u1-X27"},{"t":"경사로","mis":"SC3-1-u1-X27"}],"explanation":["막대처럼 생겼어요.","뚜껑을 열어요.","병따개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#7','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C31',2,'ox','auto','주스 통 들어 올리기 ②는 ①보다 큰 힘이 들었어요.',ARRAY['SC3-1-u1-X25']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C31","difficulty":2,"kind":"ox","stem":"주스 통 들어 올리기 ②는 ①보다 큰 힘이 들었어요.","answer":"X","reason_options":[{"t":"지레를 이용하면 손으로 곧장 들 때보다 작은 힘이 들기 때문에","correct":true},{"t":"도구를 쓰면 힘이 더 들기 때문에","mis":"SC3-1-u1-X25"}],"mis":"SC3-1-u1-X25","explanation":["마지막 줄을 읽어요.","작은 힘이었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 주스 통을 손으로 곧장 들어 올렸다.","② 받침대 위 나무판자 한쪽 끝에 주스 통을 놓고 반대쪽을 눌렀다.","③ 책을 쌓아 나무판자를 비스듬히 세우고 주스 통을 밀어 올렸다.","②와 ③은 ①보다 작은 힘이 들었다."],"title":"주스 통 들어 올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#8','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C30',2,'mc','auto','주스 통 들어 올리기 ③에서 비스듬히 세운 나무판자는 무엇을 이용한 것인가요?',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C30","difficulty":2,"kind":"mc","stem":"주스 통 들어 올리기 ③에서 비스듬히 세운 나무판자는 무엇을 이용한 것인가요?","options":[{"t":"빗면","correct":true},{"t":"지레","mis":"SC3-1-u1-X26"},{"t":"저울","mis":"SC3-1-u1-X26"},{"t":"수평대","mis":"SC3-1-u1-X26"}],"explanation":["③을 읽어요.","비스듬해요.","빗면이에요."],"asset":{"type":"passage","lines":["① 주스 통을 손으로 곧장 들어 올렸다.","② 받침대 위 나무판자 한쪽 끝에 주스 통을 놓고 반대쪽을 눌렀다.","③ 책을 쌓아 나무판자를 비스듬히 세우고 주스 통을 밀어 올렸다.","②와 ③은 ①보다 작은 힘이 들었다."],"title":"주스 통 들어 올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#9','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C33',2,'mc','auto','옛날 사람들이 무거운 고인돌의 윗돌을 올린 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X28','SC3-1-u1-X05','SC3-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C33","difficulty":2,"kind":"mc","stem":"옛날 사람들이 무거운 고인돌의 윗돌을 올린 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 사람이 힘을 합치거나 도구를 이용했어요","correct":true},{"t":"한 사람이 맨손으로 번쩍 들었어요","mis":"SC3-1-u1-X28"},{"t":"돌이 저절로 올라갔어요","mis":"SC3-1-u1-X05"},{"t":"돌을 바라보기만 했어요","mis":"SC3-1-u1-X02"}],"explanation":["아주 무거운 돌이에요.","혼자는 어려워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_basic#10','sci',3,1,'u1','L06','g3_1_sci_u1_L06_basic','lesson_basic','SC3-1-u1-C31',3,'mc','auto','무거운 짐을 트럭에 실을 때 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-1-u1-X29','SC3-1-u1-X28']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C31","difficulty":3,"kind":"mc","stem":"무거운 짐을 트럭에 실을 때 가장 알맞은 방법은 무엇인가요?","options":[{"t":"경사판을 걸쳐 밀어 올려요","correct":true},{"t":"맨손으로 번쩍 들어 던져요","mis":"SC3-1-u1-X29"},{"t":"발로 차서 올려요","mis":"SC3-1-u1-X29"},{"t":"혼자 무리해서 들어 올려요","mis":"SC3-1-u1-X28"}],"explanation":["빗면을 떠올려요.","비스듬히 밀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#1','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C29',2,'blank','auto','「가위와 시소는 모두 (      ) 도구예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X27','SC3-1-u1-X26']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C29","difficulty":2,"kind":"blank","stem":"「가위와 시소는 모두 (      ) 도구예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"지레를 이용한","correct":true},{"t":"빗면을 이용한","mis":"SC3-1-u1-X27"},{"t":"저울을 이용한","mis":"SC3-1-u1-X26"},{"t":"경사로를 이용한","mis":"SC3-1-u1-X27"}],"explanation":["막대를 받쳐요.","지레예요.","「지레를 이용한」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#2','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C33',2,'mc','auto','혼자 들기 어려운 무거운 물체를 옮길 때 알맞은 생각은 무엇인가요?',ARRAY['SC3-1-u1-X28','SC3-1-u1-X05','SC3-1-u1-X25']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C33","difficulty":2,"kind":"mc","stem":"혼자 들기 어려운 무거운 물체를 옮길 때 알맞은 생각은 무엇인가요?","options":[{"t":"여럿이 힘을 합치거나 도구를 이용해요","correct":true},{"t":"혼자 맨손으로만 들어야 해요","mis":"SC3-1-u1-X28"},{"t":"물체가 저절로 옮겨지기를 기다려요","mis":"SC3-1-u1-X05"},{"t":"도구를 쓰면 더 힘들어요","mis":"SC3-1-u1-X25"}],"explanation":["고인돌을 떠올려요.","함께 또는 도구로요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#3','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C32',3,'error','auto','친구들이 학교에서 찾은 도구를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C32","difficulty":3,"kind":"error","stem":"친구들이 학교에서 찾은 도구를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「현관 입구 경사로는 지레를 이용한 거야.」","correct":true,"mis_target":"SC3-1-u1-X27"},{"t":"친구 가 — 「놀이터 시소는 지레를 이용한 거야.」","mis":"SC3-1-u1-X27"},{"t":"친구 다 — 「계단은 빗면을 이용한 거야.」","mis":"SC3-1-u1-X27"}],"explanation":["경사로는 비스듬해요.","빗면이에요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#4','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C30',3,'mc','auto','빗면을 이용하면 좋은 때는 언제인가요?',ARRAY['SC3-1-u1-X26','SC3-1-u1-X27','SC3-1-u1-X29']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C30","difficulty":3,"kind":"mc","stem":"빗면을 이용하면 좋은 때는 언제인가요?","options":[{"t":"무거운 상자를 높은 곳으로 옮길 때","correct":true},{"t":"물체의 무게를 정확히 잴 때","mis":"SC3-1-u1-X26"},{"t":"종이를 자를 때","mis":"SC3-1-u1-X27"},{"t":"공을 멀리 던질 때","mis":"SC3-1-u1-X29"}],"explanation":["비스듬히 밀어 올려요.","높은 곳이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#5','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C32',3,'mc','auto','지레를 이용한 도구끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C32","difficulty":3,"kind":"mc","stem":"지레를 이용한 도구끼리 모은 것은 무엇인가요?","options":[{"t":"가위, 병따개, 시소","correct":true},{"t":"계단, 경사로, 미끄럼틀","mis":"SC3-1-u1-X27"},{"t":"가위, 계단, 시소","mis":"SC3-1-u1-X27"},{"t":"병따개, 미끄럼틀, 경사로","mis":"SC3-1-u1-X27"}],"explanation":["셋 다 지레여야 해요.","비스듬한 것은 빼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#6','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C31',3,'ox','auto','지레나 빗면을 이용하면 무거운 물체도 손으로 곧장 들 때보다 작은 힘으로 옮길 수 있어요.',ARRAY['SC3-1-u1-X25']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C31","difficulty":3,"kind":"ox","stem":"지레나 빗면을 이용하면 무거운 물체도 손으로 곧장 들 때보다 작은 힘으로 옮길 수 있어요.","answer":"O","reason_options":[{"t":"도구가 드는 힘을 작게 해 주기 때문에","correct":true},{"t":"도구를 쓰나 안 쓰나 드는 힘은 똑같기 때문에","mis":"SC3-1-u1-X25"}],"mis":"SC3-1-u1-X25","explanation":["주스 통을 떠올려요.","작은 힘이 들었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#7','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C29',3,'mc','auto','주스 통 들어 올리기 ②에서 쓴 도구는 무엇인가요?',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C29","difficulty":3,"kind":"mc","stem":"주스 통 들어 올리기 ②에서 쓴 도구는 무엇인가요?","options":[{"t":"지레","correct":true},{"t":"빗면","mis":"SC3-1-u1-X26"},{"t":"저울","mis":"SC3-1-u1-X26"},{"t":"수평대","mis":"SC3-1-u1-X26"}],"explanation":["②를 읽어요.","받침대 위 판자예요.","지레예요."],"asset":{"type":"passage","lines":["① 주스 통을 손으로 곧장 들어 올렸다.","② 받침대 위 나무판자 한쪽 끝에 주스 통을 놓고 반대쪽을 눌렀다.","③ 책을 쌓아 나무판자를 비스듬히 세우고 주스 통을 밀어 올렸다.","②와 ③은 ①보다 작은 힘이 들었다."],"title":"주스 통 들어 올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#8','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C31',4,'mc','auto','친구가 「도구를 쓰면 준비하느라 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X25','SC3-1-u1-X26']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C31","difficulty":4,"kind":"mc","stem":"친구가 「도구를 쓰면 준비하느라 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「지레나 빗면을 쓰면 무거운 물체를 더 작은 힘으로 옮길 수 있어.」","correct":true},{"t":"「맞아, 맨손이 더 쉬워.」","mis":"SC3-1-u1-X25"},{"t":"「도구를 써도 힘은 똑같아.」","mis":"SC3-1-u1-X25"},{"t":"「빗면은 막대를 받친 도구야.」","mis":"SC3-1-u1-X26"}],"explanation":["주스 통을 떠올려요.","작은 힘이었어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#9','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C30',4,'mc','auto','친구가 「계단은 걷는 곳일 뿐 도구와 관계없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X27','SC3-1-u1-X26']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C30","difficulty":4,"kind":"mc","stem":"친구가 「계단은 걷는 곳일 뿐 도구와 관계없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「계단은 비스듬한 면을 이용해 높은 곳에 쉽게 오르게 하는 빗면이야.」","correct":true},{"t":"「맞아, 계단은 아무 도구도 이용하지 않아.」","mis":"SC3-1-u1-X27"},{"t":"「계단은 지레를 이용한 거야.」","mis":"SC3-1-u1-X27"},{"t":"「계단은 무게를 재는 도구야.」","mis":"SC3-1-u1-X26"}],"explanation":["계단 옆모습을 떠올려요.","비스듬해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L06_challenge#10','sci',3,1,'u1','L06','g3_1_sci_u1_L06_challenge','lesson_challenge','SC3-1-u1-C31',4,'essay','teacher','주스 통 들어 올리기 ①~③을 보고, 드는 힘이 작았던 방법 두 가지와 이용한 도구 이름을 쓰고 도구를 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C31","difficulty":4,"kind":"essay","stem":"주스 통 들어 올리기 ①~③을 보고, 드는 힘이 작았던 방법 두 가지와 이용한 도구 이름을 쓰고 도구를 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: ②는 지레를, ③은 빗면을 이용해 주스 통을 들어 올렸다. 지레나 빗면 같은 도구를 쓰면 손으로 곧장 들 때보다 작은 힘으로 무거운 물체를 들어 올릴 수 있다.","scoring_points":["②와 ③을 골랐는가","지레와 빗면을 바르게 짝 지었는가","작은 힘이 든다는 좋은 점을 썼는가"]},"explanation":["마지막 줄을 읽어요.","②와 ③이에요.","도구 이름을 써요."],"asset":{"type":"passage","lines":["① 주스 통을 손으로 곧장 들어 올렸다.","② 받침대 위 나무판자 한쪽 끝에 주스 통을 놓고 반대쪽을 눌렀다.","③ 책을 쌓아 나무판자를 비스듬히 세우고 주스 통을 밀어 올렸다.","②와 ③은 ①보다 작은 힘이 들었다."],"title":"주스 통 들어 올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#1','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C35',1,'mc','auto','무거운 짐을 높은 곳에 올릴 때 알맞은 방법은 무엇인가요?',ARRAY['SC3-1-u1-X29']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C35","difficulty":1,"kind":"mc","stem":"무거운 짐을 높은 곳에 올릴 때 알맞은 방법은 무엇인가요?","options":[{"t":"경사로(빗면)로 밀어 올려요","correct":true},{"t":"맨손으로 번쩍 들어요","mis":"SC3-1-u1-X29"},{"t":"발로 차 올려요","mis":"SC3-1-u1-X29"},{"t":"그냥 던져 올려요","mis":"SC3-1-u1-X29"}],"explanation":["빗면을 떠올려요.","밀어 올려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#2','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C36',1,'mc','auto','찾은 도구를 친구와 나누면 어떤 점이 좋은가요?',ARRAY['SC3-1-u1-X31','SC3-1-u1-X25']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C36","difficulty":1,"kind":"mc","stem":"찾은 도구를 친구와 나누면 어떤 점이 좋은가요?","options":[{"t":"더 많은 도구를 알 수 있어요","correct":true},{"t":"아무 도움이 안 돼요","mis":"SC3-1-u1-X31"},{"t":"도구가 사라져요","mis":"SC3-1-u1-X31"},{"t":"힘이 더 들어요","mis":"SC3-1-u1-X25"}],"explanation":["마지막 줄을 떠올려요.","더 많아졌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#3','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C34',1,'ox','auto','지레와 빗면 도구는 집, 학교, 놀이터처럼 우리 생활 곳곳에 있어요.',ARRAY['SC3-1-u1-X30']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C34","difficulty":1,"kind":"ox","stem":"지레와 빗면 도구는 집, 학교, 놀이터처럼 우리 생활 곳곳에 있어요.","answer":"O","reason_options":[{"t":"가위·계단·미끄럼틀처럼 가까운 곳에서 쓰이기 때문에","correct":true},{"t":"도구는 공장 같은 특별한 곳에만 있기 때문에","mis":"SC3-1-u1-X30"}],"mis":"SC3-1-u1-X30","explanation":["주변을 둘러봐요.","가위도 도구예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#4','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C34',1,'sa','auto','놀이터에서 비스듬한 면을 따라 미끄러져 내려오는 놀이 기구는 빗면을 이용한 것이에요. 이 놀이 기구의 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C34","difficulty":1,"kind":"sa","stem":"놀이터에서 비스듬한 면을 따라 미끄러져 내려오는 놀이 기구는 빗면을 이용한 것이에요. 이 놀이 기구의 이름을 쓰세요.","answer":["미끄럼틀"],"explanation":["놀이터를 떠올려요.","쭉 미끄러져요.","미끄럼틀이에요."],"mis":"SC3-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#5','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C35',2,'match','auto','하고 싶은 일과 알맞은 도구를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C35","difficulty":2,"kind":"match","stem":"하고 싶은 일과 알맞은 도구를 이으세요.","pairs":[{"l":"종이를 작은 힘으로 잘라요","r":"가위"},{"l":"병뚜껑을 쉽게 열어요","r":"병따개"},{"l":"휠체어로 건물에 들어가요","r":"경사로"}],"mis":"SC3-1-u1-X29","explanation":["무엇을 하려고 하나요?","알맞은 도구가 있어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#6','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C34',2,'mc','auto','도구 탐정 기록에서 빗면을 이용한 것끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C34","difficulty":2,"kind":"mc","stem":"도구 탐정 기록에서 빗면을 이용한 것끼리 모은 것은 무엇인가요?","options":[{"t":"계단, 비탈길","correct":true},{"t":"가위, 병따개","mis":"SC3-1-u1-X27"},{"t":"시소, 가위","mis":"SC3-1-u1-X27"},{"t":"병따개, 계단","mis":"SC3-1-u1-X27"}],"explanation":["비스듬한 것을 찾아요.","학교와 길에 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["집 — 가위로 종이를 자르고 병따개로 뚜껑을 열었다.","학교 — 계단을 오르고 놀이터에서 시소를 탔다.","길 — 비탈길로 자전거를 끌고 올라갔다.","모둠 친구들과 찾은 도구를 모아 보니 더 많아졌다."],"title":"도구 탐정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#7','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C37',2,'ox','auto','도구를 쓰면 무거운 일도 작은 힘으로 할 수 있어 생활이 편해져요.',ARRAY['SC3-1-u1-X32']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C37","difficulty":2,"kind":"ox","stem":"도구를 쓰면 무거운 일도 작은 힘으로 할 수 있어 생활이 편해져요.","answer":"O","reason_options":[{"t":"도구가 드는 힘을 줄여 주기 때문에","correct":true},{"t":"도구를 쓰면 일이 더 불편해지기 때문에","mis":"SC3-1-u1-X32"}],"mis":"SC3-1-u1-X32","explanation":["도구가 하는 일이에요.","힘을 줄여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#8','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C36',2,'mc','auto','찾은 도구를 친구와 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X31']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C36","difficulty":2,"kind":"mc","stem":"찾은 도구를 친구와 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"찾은 도구와 쓰이는 곳을 적어 친구에게 소개해요","correct":true},{"t":"찾은 도구를 혼자만 알고 숨겨요","mis":"SC3-1-u1-X31"},{"t":"친구가 찾은 도구는 듣지 않아요","mis":"SC3-1-u1-X31"},{"t":"도구 이름만 크게 외치고 끝내요","mis":"SC3-1-u1-X31"}],"explanation":["조사하고 이야기해요.","적어서 소개해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#9','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C35',2,'mc','auto','친구가 무거운 화분을 높은 곳으로 옮기려고 해요. 어떻게 도우면 좋을까요?',ARRAY['SC3-1-u1-X29','SC3-1-u1-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C35","difficulty":2,"kind":"mc","stem":"친구가 무거운 화분을 높은 곳으로 옮기려고 해요. 어떻게 도우면 좋을까요?","options":[{"t":"경사판(빗면)에 올려 함께 밀어요","correct":true},{"t":"맨손으로 한 번에 들게 해요","mis":"SC3-1-u1-X29"},{"t":"발로 굴려 옮겨요","mis":"SC3-1-u1-X29"},{"t":"화분이 저절로 올라가기를 기다려요","mis":"SC3-1-u1-X05"}],"explanation":["높은 곳이에요.","빗면을 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_basic#10','sci',3,1,'u1','L07','g3_1_sci_u1_L07_basic','lesson_basic','SC3-1-u1-C37',3,'mc','auto','우리 생활에 지레와 빗면 도구가 없다면 생길 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X32','SC3-1-u1-X25']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C37","difficulty":3,"kind":"mc","stem":"우리 생활에 지레와 빗면 도구가 없다면 생길 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"무거운 일을 할 때 훨씬 큰 힘이 들어요","correct":true},{"t":"일이 더 쉬워져요","mis":"SC3-1-u1-X32"},{"t":"힘이 전혀 들지 않아요","mis":"SC3-1-u1-X25"},{"t":"아무 차이가 없어요","mis":"SC3-1-u1-X32"}],"explanation":["도구가 하던 일을 떠올려요.","힘을 줄여 줬어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#1','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C37',2,'blank','auto','「도구를 쓰면 무거운 일도 (      ) 힘으로 할 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X25']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C37","difficulty":2,"kind":"blank","stem":"「도구를 쓰면 무거운 일도 (      ) 힘으로 할 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"작은","correct":true},{"t":"더 큰","mis":"SC3-1-u1-X25"},{"t":"똑같은","mis":"SC3-1-u1-X25"},{"t":"두 배의","mis":"SC3-1-u1-X25"}],"explanation":["도구가 돕는 일이에요.","힘이 줄어요.","「작은」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#2','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C34',2,'mc','auto','집에서 찾을 수 있는 지레 도구는 무엇인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C34","difficulty":2,"kind":"mc","stem":"집에서 찾을 수 있는 지레 도구는 무엇인가요?","options":[{"t":"집게","correct":true},{"t":"계단","mis":"SC3-1-u1-X27"},{"t":"비탈길","mis":"SC3-1-u1-X27"},{"t":"경사로","mis":"SC3-1-u1-X27"}],"explanation":["손에 쥐고 써요.","빨래를 집어요.","집게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#3','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C35',3,'error','auto','친구들이 상황에 맞는 방법을 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['SC3-1-u1-X29']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C35","difficulty":3,"kind":"error","stem":"친구들이 상황에 맞는 방법을 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"친구 가 — 「무거운 상자를 트럭에 실을 때 맨손으로 던져 올릴래.」","correct":true,"mis_target":"SC3-1-u1-X29"},{"t":"친구 나 — 「병뚜껑을 열 때 병따개를 쓸래.」","mis":"SC3-1-u1-X29"},{"t":"친구 다 — 「수레를 높은 곳에 올릴 때 경사로를 쓸래.」","mis":"SC3-1-u1-X29"}],"explanation":["던지면 위험해요.","도구를 써야 해요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#4','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C34',3,'mc','auto','도구 탐정 놀이에서 찾은 것 가운데 지레나 빗면을 이용한 도구가 아닌 것은 무엇인가요?',ARRAY['SC3-1-u1-X30']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C34","difficulty":3,"kind":"mc","stem":"도구 탐정 놀이에서 찾은 것 가운데 지레나 빗면을 이용한 도구가 아닌 것은 무엇인가요?","options":[{"t":"텔레비전","correct":true},{"t":"가위","mis":"SC3-1-u1-X30"},{"t":"미끄럼틀","mis":"SC3-1-u1-X30"},{"t":"시소","mis":"SC3-1-u1-X30"}],"explanation":["하나씩 따져요.","막대도 비스듬한 면도 아니에요.","텔레비전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#5','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C36',3,'mc','auto','도구 탐정 기록의 마지막 줄에서 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u1-X31','SC3-1-u1-X30']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C36","difficulty":3,"kind":"mc","stem":"도구 탐정 기록의 마지막 줄에서 알 수 있는 것은 무엇인가요?","options":[{"t":"찾은 도구를 친구와 나누면 더 많은 도구를 알 수 있어요","correct":true},{"t":"도구는 혼자 찾는 것이 가장 좋아요","mis":"SC3-1-u1-X31"},{"t":"친구와 나누면 도구가 줄어들어요","mis":"SC3-1-u1-X31"},{"t":"도구는 학교에만 있어요","mis":"SC3-1-u1-X30"}],"explanation":["마지막 줄을 읽어요.","더 많아졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["집 — 가위로 종이를 자르고 병따개로 뚜껑을 열었다.","학교 — 계단을 오르고 놀이터에서 시소를 탔다.","길 — 비탈길로 자전거를 끌고 올라갔다.","모둠 친구들과 찾은 도구를 모아 보니 더 많아졌다."],"title":"도구 탐정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#6','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C35',3,'ox','auto','높은 곳에 있는 건물 입구로 휠체어가 들어가려면 경사로가 도움이 돼요.',ARRAY['SC3-1-u1-X29']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C35","difficulty":3,"kind":"ox","stem":"높은 곳에 있는 건물 입구로 휠체어가 들어가려면 경사로가 도움이 돼요.","answer":"O","reason_options":[{"t":"빗면인 경사로를 이용하면 작은 힘으로 밀어 올릴 수 있기 때문에","correct":true},{"t":"휠체어는 계단으로 들어 올리는 것이 더 쉽기 때문에","mis":"SC3-1-u1-X29"}],"mis":"SC3-1-u1-X29","explanation":["경사로를 떠올려요.","비스듬히 밀어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#7','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C37',3,'mc','auto','경사로, 가위, 병따개가 생활 곳곳에 쓰이는 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X25','SC3-1-u1-X32','SC3-1-u1-X30']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C37","difficulty":3,"kind":"mc","stem":"경사로, 가위, 병따개가 생활 곳곳에 쓰이는 까닭은 무엇인가요?","options":[{"t":"작은 힘으로 일을 편하게 할 수 있기 때문에","correct":true},{"t":"힘이 더 들어 운동이 되기 때문에","mis":"SC3-1-u1-X25"},{"t":"보기에 멋지기만 하기 때문에","mis":"SC3-1-u1-X32"},{"t":"특별한 사람만 쓰기 때문에","mis":"SC3-1-u1-X30"}],"explanation":["도구가 하는 일이에요.","힘을 줄여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#8','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C34',4,'mc','auto','친구가 「지레나 빗면은 공장이나 공사장에만 있어서 우리 집에는 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X30','SC3-1-u1-X32','SC3-1-u1-X27']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C34","difficulty":4,"kind":"mc","stem":"친구가 「지레나 빗면은 공장이나 공사장에만 있어서 우리 집에는 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「가위나 병따개, 계단처럼 우리 집에도 있어.」","correct":true},{"t":"「맞아, 우리 집에는 없어.」","mis":"SC3-1-u1-X30"},{"t":"「도구는 생활과 관계없어.」","mis":"SC3-1-u1-X32"},{"t":"「계단은 지레야.」","mis":"SC3-1-u1-X27"}],"explanation":["집 안을 떠올려요.","가위가 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#9','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C36',4,'mc','auto','친구가 「내가 찾은 도구는 나만 알고 싶어. 친구들 것은 안 들을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X31','SC3-1-u1-X32']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C36","difficulty":4,"kind":"mc","stem":"친구가 「내가 찾은 도구는 나만 알고 싶어. 친구들 것은 안 들을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「서로 찾은 도구를 나누면 모두 더 많은 도구를 알 수 있어.」","correct":true},{"t":"「맞아, 혼자 아는 게 좋아.」","mis":"SC3-1-u1-X31"},{"t":"「나누면 도구가 사라져.」","mis":"SC3-1-u1-X31"},{"t":"「도구는 찾을 필요가 없어.」","mis":"SC3-1-u1-X32"}],"explanation":["나누면 어떻게 되나요?","더 많이 알아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L07_challenge#10','sci',3,1,'u1','L07','g3_1_sci_u1_L07_challenge','lesson_challenge','SC3-1-u1-C35',4,'essay','teacher','우리 생활에서 지레를 이용한 도구 하나와 빗면을 이용한 도구 하나를 찾아 쓰고, 각각 어떤 일을 작은 힘으로 하게 도와주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C35","difficulty":4,"kind":"essay","stem":"우리 생활에서 지레를 이용한 도구 하나와 빗면을 이용한 도구 하나를 찾아 쓰고, 각각 어떤 일을 작은 힘으로 하게 도와주는지 쓰세요.","answer_guide":{"answer":"예: 가위는 지레를 이용해 종이를 작은 힘으로 자르게 돕는다. 경사로는 빗면을 이용해 무거운 수레나 휠체어를 작은 힘으로 밀어 올리게 돕는다.","scoring_points":["지레 도구를 바르게 썼는가","빗면 도구를 바르게 썼는가","각 도구가 돕는 일을 썼는가"]},"explanation":["집과 학교를 떠올려요.","하나씩 찾아요.","돕는 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#1','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C39',1,'mc','auto','입는 로봇을 입으면 무거운 물건을 어떻게 들 수 있나요?',ARRAY['SC3-1-u1-X34']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C39","difficulty":1,"kind":"mc","stem":"입는 로봇을 입으면 무거운 물건을 어떻게 들 수 있나요?","options":[{"t":"작은 힘으로 들 수 있어요","correct":true},{"t":"더 큰 힘이 들어요","mis":"SC3-1-u1-X34"},{"t":"들 수 없어요","mis":"SC3-1-u1-X34"},{"t":"힘이 똑같이 들어요","mis":"SC3-1-u1-X34"}],"explanation":["로봇이 도와줘요.","힘을 더해 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#2','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C38',1,'mc','auto','입는 로봇은 무엇인가요?',ARRAY['SC3-1-u1-X33']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C38","difficulty":1,"kind":"mc","stem":"입는 로봇은 무엇인가요?","options":[{"t":"몸에 입어 힘을 더해 주는 기계","correct":true},{"t":"밥을 해 주는 기계","mis":"SC3-1-u1-X33"},{"t":"노래를 들려주는 기계","mis":"SC3-1-u1-X33"},{"t":"길을 알려 주는 기계","mis":"SC3-1-u1-X33"}],"explanation":["이름에 답이 있어요.","입어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#3','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C40',1,'ox','auto','입는 로봇은 공사장이나 병원처럼 힘이 많이 드는 일을 하는 곳에서 도움을 줘요.',ARRAY['SC3-1-u1-X35']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C40","difficulty":1,"kind":"ox","stem":"입는 로봇은 공사장이나 병원처럼 힘이 많이 드는 일을 하는 곳에서 도움을 줘요.","answer":"O","reason_options":[{"t":"무거운 것을 들거나 사람을 일으키는 일을 작은 힘으로 하게 돕기 때문에","correct":true},{"t":"입는 로봇은 가만히 쉬는 곳에서만 쓰이기 때문에","mis":"SC3-1-u1-X35"}],"mis":"SC3-1-u1-X35","explanation":["돕는 곳을 떠올려요.","힘든 일을 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#4','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C38',1,'sa','auto','팔이나 다리 같은 몸에 입어 힘을 더해 주는 로봇을 「○○ 로봇」이라고 해요. ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u1-C38","difficulty":1,"kind":"sa","stem":"팔이나 다리 같은 몸에 입어 힘을 더해 주는 로봇을 「○○ 로봇」이라고 해요. ○○에 알맞은 말을 쓰세요.","answer":["입는"],"explanation":["옷처럼 해요.","몸에 걸쳐요.","「입는」이에요."],"mis":"SC3-1-u1-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#5','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C40',2,'match','auto','입는 로봇이 돕는 곳과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u1-C40","difficulty":2,"kind":"match","stem":"입는 로봇이 돕는 곳과 하는 일을 알맞게 이으세요.","pairs":[{"l":"공사장","r":"무거운 자재를 들어요"},{"l":"병원","r":"환자를 안전하게 일으켜요"},{"l":"소방","r":"무거운 장비를 메요"}],"mis":"SC3-1-u1-X35","explanation":["기록을 읽어요.","곳마다 일이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["공사장 — 무거운 자재를 드는 사람이 입는 로봇을 입었다.","병원 — 환자를 안전하게 일으킬 때 입는 로봇이 도왔다.","소방 — 무거운 장비를 메고 계단을 오를 때 힘을 더해 주었다.","농장 — 짐을 옮길 때 허리와 다리를 도왔다."],"title":"입는 로봇이 돕는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#6','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C41',2,'mc','auto','입는 로봇은 어떤 도구가 발전한 모습이라고 할 수 있나요?',ARRAY['SC3-1-u1-X36']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C41","difficulty":2,"kind":"mc","stem":"입는 로봇은 어떤 도구가 발전한 모습이라고 할 수 있나요?","options":[{"t":"작은 힘으로 들게 돕는 도구","correct":true},{"t":"소리를 키우는 도구","mis":"SC3-1-u1-X36"},{"t":"색을 칠하는 도구","mis":"SC3-1-u1-X36"},{"t":"길이를 재는 도구","mis":"SC3-1-u1-X36"}],"explanation":["지레와 빗면을 떠올려요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#7','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C39',2,'ox','auto','입는 로봇을 입으면 같은 물건을 들 때 힘이 더 많이 들어요.',ARRAY['SC3-1-u1-X34']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C39","difficulty":2,"kind":"ox","stem":"입는 로봇을 입으면 같은 물건을 들 때 힘이 더 많이 들어요.","answer":"X","reason_options":[{"t":"입는 로봇이 힘을 더해 주어 작은 힘으로 들 수 있기 때문에","correct":true},{"t":"로봇이 무거워서 늘 힘이 더 들기 때문에","mis":"SC3-1-u1-X34"}],"mis":"SC3-1-u1-X34","explanation":["로봇이 하는 일이에요.","힘을 더해 줘요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#8','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C40',2,'mc','auto','입는 로봇이 가장 도움이 될 곳은 어디인가요?',ARRAY['SC3-1-u1-X35']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C40","difficulty":2,"kind":"mc","stem":"입는 로봇이 가장 도움이 될 곳은 어디인가요?","options":[{"t":"무거운 짐을 많이 나르는 농장","correct":true},{"t":"조용히 책을 읽는 도서관","mis":"SC3-1-u1-X35"},{"t":"그림을 그리는 미술실","mis":"SC3-1-u1-X35"},{"t":"잠을 자는 침실","mis":"SC3-1-u1-X35"}],"explanation":["힘이 많이 드는 곳이에요.","짐을 날라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#9','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C39',2,'mc','auto','입는 로봇의 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X34','SC3-1-u1-X33','SC3-1-u1-X36']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C39","difficulty":2,"kind":"mc","stem":"입는 로봇의 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"힘든 일을 더 편하게 할 수 있어요","correct":true},{"t":"힘이 더 많이 들어요","mis":"SC3-1-u1-X34"},{"t":"사람이 없어도 혼자 모든 일을 해요","mis":"SC3-1-u1-X33"},{"t":"무게를 정확히 재 줘요","mis":"SC3-1-u1-X36"}],"explanation":["입으면 어떻게 되나요?","편해져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_basic#10','sci',3,1,'u1','L08','g3_1_sci_u1_L08_basic','lesson_basic','SC3-1-u1-C41',3,'mc','auto','지레, 빗면, 입는 로봇의 같은 점으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X33','SC3-1-u1-X34','SC3-1-u1-X36']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C41","difficulty":3,"kind":"mc","stem":"지레, 빗면, 입는 로봇의 같은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"무거운 물체를 작은 힘으로 다루게 도와요","correct":true},{"t":"모두 사람이 입는 기계예요","mis":"SC3-1-u1-X33"},{"t":"쓰면 힘이 더 들어요","mis":"SC3-1-u1-X34"},{"t":"모두 무게를 재는 데 써요","mis":"SC3-1-u1-X36"}],"explanation":["셋이 하는 일이에요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#1','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C38',2,'blank','auto','「입는 로봇은 몸에 입어 사람에게 (      ) 더해 주는 기계예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u1-X36','SC3-1-u1-X33']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C38","difficulty":2,"kind":"blank","stem":"「입는 로봇은 몸에 입어 사람에게 (      ) 더해 주는 기계예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"힘을","correct":true},{"t":"무게를","mis":"SC3-1-u1-X36"},{"t":"키를","mis":"SC3-1-u1-X33"},{"t":"목소리를","mis":"SC3-1-u1-X33"}],"explanation":["무엇을 더해 줄까요?","들 때 필요한 것이에요.","「힘을」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#2','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C40',2,'mc','auto','병원에서 입는 로봇이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X33','SC3-1-u1-X35']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C40","difficulty":2,"kind":"mc","stem":"병원에서 입는 로봇이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"환자를 안전하게 일으키도록 도와요","correct":true},{"t":"환자 대신 밥을 먹어요","mis":"SC3-1-u1-X33"},{"t":"병원 음악을 틀어요","mis":"SC3-1-u1-X35"},{"t":"약 이름을 정해요","mis":"SC3-1-u1-X35"}],"explanation":["기록의 둘째 줄이에요.","일으켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#3','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C39',3,'error','auto','친구들이 입는 로봇을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u1-X34','SC3-1-u1-X33','SC3-1-u1-X35']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C39","difficulty":3,"kind":"error","stem":"친구들이 입는 로봇을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「입는 로봇을 입으면 무거운 상자를 들 때 힘이 더 들어.」","correct":true,"mis_target":"SC3-1-u1-X34"},{"t":"친구 가 — 「입는 로봇은 힘을 더해 주는 기계야.」","mis":"SC3-1-u1-X33"},{"t":"친구 나 — 「소방관이 무거운 장비를 멜 때 도움이 돼.」","mis":"SC3-1-u1-X35"}],"explanation":["힘을 더해 줘요.","작은 힘이에요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#4','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C40',3,'mc','auto','입는 로봇이 돕는 곳에 나온 일의 같은 점은 무엇인가요?',ARRAY['SC3-1-u1-X35','SC3-1-u1-X36','SC3-1-u1-X33']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C40","difficulty":3,"kind":"mc","stem":"입는 로봇이 돕는 곳에 나온 일의 같은 점은 무엇인가요?","options":[{"t":"모두 힘이 많이 드는 일이에요","correct":true},{"t":"모두 힘이 거의 들지 않는 일이에요","mis":"SC3-1-u1-X35"},{"t":"모두 무게를 재는 일이에요","mis":"SC3-1-u1-X36"},{"t":"모두 로봇 혼자 하는 일이에요","mis":"SC3-1-u1-X33"}],"explanation":["네 곳을 읽어요.","무겁고 힘들어요.","첫 번째예요."],"asset":{"type":"passage","lines":["공사장 — 무거운 자재를 드는 사람이 입는 로봇을 입었다.","병원 — 환자를 안전하게 일으킬 때 입는 로봇이 도왔다.","소방 — 무거운 장비를 메고 계단을 오를 때 힘을 더해 주었다.","농장 — 짐을 옮길 때 허리와 다리를 도왔다."],"title":"입는 로봇이 돕는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#5','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C41',3,'mc','auto','입는 로봇이 앞에서 배운 지레·빗면과 닮은 점은 무엇인가요?',ARRAY['SC3-1-u1-X26','SC3-1-u1-X34','SC3-1-u1-X36']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C41","difficulty":3,"kind":"mc","stem":"입는 로봇이 앞에서 배운 지레·빗면과 닮은 점은 무엇인가요?","options":[{"t":"무거운 일을 작은 힘으로 하게 도와요","correct":true},{"t":"비스듬한 면으로 되어 있어요","mis":"SC3-1-u1-X26"},{"t":"무거운 일을 더 힘들게 해요","mis":"SC3-1-u1-X34"},{"t":"무게를 숫자로 알려 줘요","mis":"SC3-1-u1-X36"}],"explanation":["도구가 하는 일이에요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#6','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C38',3,'ox','auto','입는 로봇은 사람이 입지 않아도 혼자서 공사장 일을 모두 해요.',ARRAY['SC3-1-u1-X33']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C38","difficulty":3,"kind":"ox","stem":"입는 로봇은 사람이 입지 않아도 혼자서 공사장 일을 모두 해요.","answer":"X","reason_options":[{"t":"입는 로봇은 사람이 몸에 입어 사람의 힘을 더해 주는 기계이기 때문에","correct":true},{"t":"로봇은 무엇이든 혼자서 하기 때문에","mis":"SC3-1-u1-X33"}],"mis":"SC3-1-u1-X33","explanation":["이름을 떠올려요.","입어야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#7','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C39',3,'mc','auto','무거운 짐을 하루 종일 나르는 일에 도움이 될 것은 무엇인가요?',ARRAY['SC3-1-u1-X36','SC3-1-u1-X33']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C39","difficulty":3,"kind":"mc","stem":"무거운 짐을 하루 종일 나르는 일에 도움이 될 것은 무엇인가요?","options":[{"t":"힘을 더해 주는 입는 로봇","correct":true},{"t":"시간을 알려 주는 시계","mis":"SC3-1-u1-X36"},{"t":"그림 그리는 붓","mis":"SC3-1-u1-X36"},{"t":"노래하는 기계","mis":"SC3-1-u1-X33"}],"explanation":["무거운 짐이에요.","힘이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#8','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C39',4,'mc','auto','친구가 「입는 로봇은 무거워 보이니까 입으면 힘이 더 들 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X34','SC3-1-u1-X33','SC3-1-u1-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C39","difficulty":4,"kind":"mc","stem":"친구가 「입는 로봇은 무거워 보이니까 입으면 힘이 더 들 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「입는 로봇이 힘을 더해 주어서 무거운 물건도 작은 힘으로 들 수 있어.」","correct":true},{"t":"「맞아, 힘이 더 들어.」","mis":"SC3-1-u1-X34"},{"t":"「입는 로봇은 노래만 해.」","mis":"SC3-1-u1-X33"},{"t":"「입는 로봇은 도구와 관계없어.」","mis":"SC3-1-u1-X36"}],"explanation":["로봇이 하는 일이에요.","힘을 더해 줘요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#9','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C40',4,'mc','auto','친구가 「입는 로봇은 공사장에서만 쓸 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X35','SC3-1-u1-X36']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C40","difficulty":4,"kind":"mc","stem":"친구가 「입는 로봇은 공사장에서만 쓸 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「병원, 소방, 농장처럼 힘이 많이 드는 여러 곳에서 도와.」","correct":true},{"t":"「맞아, 공사장에서만 써.」","mis":"SC3-1-u1-X35"},{"t":"「책 읽는 도서관에서 가장 많이 써.」","mis":"SC3-1-u1-X35"},{"t":"「입는 로봇은 무게를 재는 기계야.」","mis":"SC3-1-u1-X36"}],"explanation":["기록을 다시 읽어요.","네 곳이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["공사장 — 무거운 자재를 드는 사람이 입는 로봇을 입었다.","병원 — 환자를 안전하게 일으킬 때 입는 로봇이 도왔다.","소방 — 무거운 장비를 메고 계단을 오를 때 힘을 더해 주었다.","농장 — 짐을 옮길 때 허리와 다리를 도왔다."],"title":"입는 로봇이 돕는 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_L08_challenge#10','sci',3,1,'u1','L08','g3_1_sci_u1_L08_challenge','lesson_challenge','SC3-1-u1-C41',4,'essay','teacher','입는 로봇이 도움이 될 곳을 하나 골라 쓰고, 그곳에서 어떤 일을 돕는지와 지레·빗면 같은 도구와 닮은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u1-C41","difficulty":4,"kind":"essay","stem":"입는 로봇이 도움이 될 곳을 하나 골라 쓰고, 그곳에서 어떤 일을 돕는지와 지레·빗면 같은 도구와 닮은 점을 쓰세요.","answer_guide":{"answer":"예: 병원에서 환자를 안전하게 일으키는 일을 돕는다. 지레나 빗면처럼 입는 로봇도 무거운 것을 작은 힘으로 들게 도와준다.","scoring_points":["돕는 곳을 하나 골랐는가","그곳에서 돕는 일을 썼는가","작은 힘으로 들게 돕는다는 닮은 점을 썼는가"]},"explanation":["돕는 곳을 떠올려요.","하는 일을 써요.","닮은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#1','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C2',1,'mc','auto','새봄반 일지 ①에서 공이 페트병까지 가지 못했을 때는 공을 어떻게 밀었나요?',ARRAY['SC3-1-u1-X03','SC3-1-u1-X01','SC3-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C2","difficulty":1,"kind":"mc","stem":"새봄반 일지 ①에서 공이 페트병까지 가지 못했을 때는 공을 어떻게 밀었나요?","options":[{"t":"약하게 밀었다","correct":true},{"t":"세게 밀었다","mis":"SC3-1-u1-X03"},{"t":"당겼다","mis":"SC3-1-u1-X01"},{"t":"밀지 않았다","mis":"SC3-1-u1-X05"}],"explanation":["둘째 줄을 읽어요.","약하게였어요.","첫 번째예요."],"asset":{"type":"passage","lines":["페트병 두 개를 세우고 공을 굴려 넘어뜨리는 놀이를 했다.","처음에는 약하게 밀어 공이 페트병까지 가지 못했다.","다음에는 세게 밀어 공이 빠르게 굴러가 페트병이 넘어졌다.","찰흙을 손으로 눌렀더니 납작해졌다.","친구 가 — 「공이 저절로 굴러가서 페트병을 넘어뜨렸어.」"],"title":"새봄반 일지 ① 공 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#2','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C7',1,'mc','auto','새봄반 일지 ②에서 힘이 물체를 움직이게 한 것은 무엇인가요?',ARRAY['SC3-1-u1-X07','SC3-1-u1-X05','SC3-1-u1-X06']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C7","difficulty":1,"kind":"mc","stem":"새봄반 일지 ②에서 힘이 물체를 움직이게 한 것은 무엇인가요?","options":[{"t":"멈춰 있던 수레를 민 일","correct":true},{"t":"굴러오던 공을 잡은 일","mis":"SC3-1-u1-X07"},{"t":"그대로 있던 의자","mis":"SC3-1-u1-X05"},{"t":"움직이게 한 일은 없다","mis":"SC3-1-u1-X06"}],"explanation":["첫 줄을 읽어요.","수레가 움직였어요.","첫 번째예요."],"asset":{"type":"passage","lines":["멈춰 있던 수레를 밀었더니 앞으로 움직였다.","굴러오던 공을 두 손으로 잡았더니 멈췄다.","닫힌 문을 손잡이로 당겨 열었다.","아무도 건드리지 않은 의자는 그대로 있었다.","친구 나 — 「힘은 물체를 움직이게만 해.」"],"title":"새봄반 일지 ② 교실 속 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#3','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C11',1,'mc','auto','새봄반 일지 ③에서 가장 작은 힘으로 밀 수 있는 상자는 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C11","difficulty":1,"kind":"mc","stem":"새봄반 일지 ③에서 가장 작은 힘으로 밀 수 있는 상자는 무엇인가요?","options":[{"t":"㉠ 빈 상자","correct":true},{"t":"㉢ 책 5권 상자","mis":"SC3-1-u1-X09"},{"t":"㉡ 책 2권 상자","mis":"SC3-1-u1-X09"},{"t":"세 상자 모두 같다","mis":"SC3-1-u1-X12"}],"explanation":["가장 가벼운 상자예요.","아무것도 없어요.","㉠이에요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자 · ㉡ 책 2권 상자 · ㉢ 책 5권 상자","먼저 드는 힘을 예상한 뒤 하나씩 밀어 보았다.","㉢을 밀 때 가장 큰 힘이 들었다.","친구 다 — 「크기가 같으니 세 상자 모두 같은 힘이 들 거야.」"],"title":"새봄반 일지 ③ 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#4','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C20',1,'mc','auto','새봄반 일지 ④에서 ㉮와 ㉯ 가운데 더 무거운 구슬은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X16','SC3-1-u1-X14']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C20","difficulty":1,"kind":"mc","stem":"새봄반 일지 ④에서 ㉮와 ㉯ 가운데 더 무거운 구슬은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SC3-1-u1-X13"},{"t":"둘 다 같다","mis":"SC3-1-u1-X16"},{"t":"알 수 없다","mis":"SC3-1-u1-X14"}],"explanation":["기운 쪽을 봐요.","㉮ 쪽이에요.","㉮예요."],"asset":{"type":"passage","lines":["자를 휴지 심 위에 올려 수평을 맞추었다.","같은 거리에 구슬 ㉮와 ㉯를 올렸더니 ㉮ 쪽으로 기울었다.","구슬 ㉯와 ㉰를 같은 거리에 올렸더니 수평을 이루었다.","친구 가 — 「위로 올라간 쪽 구슬이 더 무거워.」"],"title":"새봄반 일지 ④ 수평 잡기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#5','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C24',1,'mc','auto','새봄반 일지 ⑤에서 전자저울로 잰 결과 더 무거운 것은 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X20']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C24","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑤에서 전자저울로 잰 결과 더 무거운 것은 무엇인가요?","options":[{"t":"물병","correct":true},{"t":"통조림","mis":"SC3-1-u1-X19"},{"t":"둘 다 같다","mis":"SC3-1-u1-X20"},{"t":"친구마다 다르다","mis":"SC3-1-u1-X20"}],"explanation":["저울 숫자를 봐요.","550이 커요.","물병이에요."],"asset":{"type":"passage","lines":["통조림과 물병을 손으로 들어 보니 친구마다 무거운 것이 달랐다.","전자저울로 재니 통조림 400 g, 물병 550 g이었다.","용수철저울에 가방 고리를 걸었더니 용수철이 늘어났다.","친구 나 — 「손으로 들어 본 게 저울보다 더 정확해.」"],"title":"새봄반 일지 ⑤ 손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#6','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C29',1,'mc','auto','새봄반 일지 ⑥에서 막대를 받침대에 걸쳐 돌을 든 도구는 무엇인가요?',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C29","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑥에서 막대를 받침대에 걸쳐 돌을 든 도구는 무엇인가요?","options":[{"t":"지레","correct":true},{"t":"빗면","mis":"SC3-1-u1-X26"},{"t":"저울","mis":"SC3-1-u1-X26"},{"t":"수평대","mis":"SC3-1-u1-X26"}],"explanation":["둘째 줄을 읽어요.","막대를 받쳤어요.","지레예요."],"asset":{"type":"passage","lines":["무거운 돌을 맨손으로 들려니 꿈쩍도 하지 않았다.","긴 막대를 받침대에 걸치고 막대 끝을 눌렀더니 돌이 들렸다.","무거운 수레는 비스듬한 판자를 따라 밀어 올렸다.","친구 다 — 「도구를 쓰면 힘이 더 들어.」"],"title":"새봄반 일지 ⑥ 무거운 돌 옮기기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#7','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C34',1,'mc','auto','새봄반 일지 ⑦에서 지레를 이용한 도구끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C34","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑦에서 지레를 이용한 도구끼리 모은 것은 무엇인가요?","options":[{"t":"가위, 병따개, 시소","correct":true},{"t":"계단, 경사로, 미끄럼틀","mis":"SC3-1-u1-X27"},{"t":"가위, 계단, 미끄럼틀","mis":"SC3-1-u1-X27"},{"t":"병따개, 경사로, 시소","mis":"SC3-1-u1-X27"}],"explanation":["막대를 받쳐 쓰는 도구예요.","비스듬한 것은 빼요.","첫 번째예요."],"asset":{"type":"passage","lines":["집에서 가위와 병따개를 찾았다.","학교에서 계단과 현관 경사로를 찾았다.","놀이터에서 시소와 미끄럼틀을 찾았다.","모둠 친구들과 찾은 도구를 모아 게시판에 붙였다.","친구 가 — 「도구는 공장에만 있는 줄 알았어.」"],"title":"새봄반 일지 ⑦ 도구 탐정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#8','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C39',1,'mc','auto','새봄반 일지 ⑧에서 입는 로봇을 입고 자재를 들 때 드는 힘은 어떤가요?',ARRAY['SC3-1-u1-X34']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C39","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑧에서 입는 로봇을 입고 자재를 들 때 드는 힘은 어떤가요?","options":[{"t":"로봇 없이 들 때보다 작다","correct":true},{"t":"로봇 없이 들 때보다 크다","mis":"SC3-1-u1-X34"},{"t":"로봇이 없을 때와 똑같다","mis":"SC3-1-u1-X34"},{"t":"아예 들 수 없다","mis":"SC3-1-u1-X34"}],"explanation":["둘째 줄을 읽어요.","작은 힘이었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["공사장 사람이 입는 로봇을 입고 무거운 자재를 들었다.","로봇 없이 들 때보다 작은 힘이 들었다.","병원에서는 환자를 일으킬 때 입는 로봇이 도왔다.","친구 나 — 「입는 로봇은 사람 없이 혼자 일하는 로봇이야.」"],"title":"새봄반 일지 ⑧ 입는 로봇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#9','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C3',2,'mc','auto','다음 가운데 당기는 힘을 쓰는 일은 무엇인가요?',ARRAY['SC3-1-u1-X01','SC3-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 당기는 힘을 쓰는 일은 무엇인가요?","options":[{"t":"두레박 줄을 끌어올리기","correct":true},{"t":"보드를 발로 밀기","mis":"SC3-1-u1-X01"},{"t":"버튼 누르기","mis":"SC3-1-u1-X01"},{"t":"구름 바라보기","mis":"SC3-1-u1-X02"}],"explanation":["내 쪽으로 오는 것이에요.","줄을 끌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#10','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C8',2,'mc','auto','자전거 브레이크를 잡으면 힘은 어떤 일을 하나요?',ARRAY['SC3-1-u1-X07','SC3-1-u1-X06','SC3-1-u1-X05']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C8","difficulty":2,"kind":"mc","stem":"자전거 브레이크를 잡으면 힘은 어떤 일을 하나요?","options":[{"t":"달리던 자전거를 멈추게 해요","correct":true},{"t":"자전거를 더 빨리 움직이게 해요","mis":"SC3-1-u1-X07"},{"t":"아무 일도 하지 않아요","mis":"SC3-1-u1-X06"},{"t":"자전거가 저절로 서요","mis":"SC3-1-u1-X05"}],"explanation":["브레이크가 하는 일이에요.","서게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#11','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C12',2,'mc','auto','짐을 실은 수레를 당길 때 짐을 더 실으면 드는 힘은 어떻게 되나요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X10']::text[],false,'{"seq":11,"concept":"SC3-1-u1-C12","difficulty":2,"kind":"mc","stem":"짐을 실은 수레를 당길 때 짐을 더 실으면 드는 힘은 어떻게 되나요?","options":[{"t":"더 큰 힘이 들어요","correct":true},{"t":"더 작은 힘이 들어요","mis":"SC3-1-u1-X09"},{"t":"당길 때는 그대로예요","mis":"SC3-1-u1-X10"},{"t":"힘이 들지 않아요","mis":"SC3-1-u1-X10"}],"explanation":["짐이 늘면 무거워요.","당길 때도 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
