INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#15','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C35',2,'mc','auto','병뚜껑을 쉽게 열고 싶을 때 쓰면 좋은 도구는 무엇인가요?',ARRAY['SC3-1-u1-X29']::text[],false,'{"seq":15,"concept":"SC3-1-u1-C35","difficulty":2,"kind":"mc","stem":"병뚜껑을 쉽게 열고 싶을 때 쓰면 좋은 도구는 무엇인가요?","options":[{"t":"병따개","correct":true},{"t":"계단","mis":"SC3-1-u1-X29"},{"t":"미끄럼틀","mis":"SC3-1-u1-X29"},{"t":"비탈길","mis":"SC3-1-u1-X29"}],"explanation":["뚜껑을 여는 도구예요.","이름에 답이 있어요.","병따개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#16','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C40',2,'mc','auto','입는 로봇이 소방에서 돕는 일은 무엇인가요?',ARRAY['SC3-1-u1-X33','SC3-1-u1-X35','SC3-1-u1-X36']::text[],false,'{"seq":16,"concept":"SC3-1-u1-C40","difficulty":2,"kind":"mc","stem":"입는 로봇이 소방에서 돕는 일은 무엇인가요?","options":[{"t":"무거운 장비를 메고 움직이게 도와요","correct":true},{"t":"불을 보며 노래를 불러 줘요","mis":"SC3-1-u1-X33"},{"t":"책을 대신 읽어 줘요","mis":"SC3-1-u1-X35"},{"t":"장비 무게를 재 줘요","mis":"SC3-1-u1-X36"}],"explanation":["소방관을 떠올려요.","장비가 무거워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#17','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C9',3,'mc','auto','바닥에 가만히 있던 공이 굴러가기 시작했어요. 알맞은 생각은 무엇인가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02','SC3-1-u1-X04']::text[],false,'{"seq":17,"concept":"SC3-1-u1-C9","difficulty":3,"kind":"mc","stem":"바닥에 가만히 있던 공이 굴러가기 시작했어요. 알맞은 생각은 무엇인가요?","options":[{"t":"무언가가 공에 힘을 주었을 것이다","correct":true},{"t":"공이 스스로 굴러가기로 했다","mis":"SC3-1-u1-X05"},{"t":"누가 공을 바라보았다","mis":"SC3-1-u1-X02"},{"t":"공 색깔이 바뀌었다","mis":"SC3-1-u1-X04"}],"explanation":["물체는 스스로 못 움직여요.","힘을 받았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#18','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C13',3,'mc','auto','빈 수레, 상자 1개 실은 수레, 상자 3개 실은 수레를 당길 때 큰 힘이 드는 차례는 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X10']::text[],false,'{"seq":18,"concept":"SC3-1-u1-C13","difficulty":3,"kind":"mc","stem":"빈 수레, 상자 1개 실은 수레, 상자 3개 실은 수레를 당길 때 큰 힘이 드는 차례는 무엇인가요?","options":[{"t":"상자 3개 → 상자 1개 → 빈 수레","correct":true},{"t":"빈 수레 → 상자 1개 → 상자 3개","mis":"SC3-1-u1-X09"},{"t":"세 수레 모두 같다","mis":"SC3-1-u1-X10"},{"t":"상자 1개 → 상자 3개 → 빈 수레","mis":"SC3-1-u1-X09"}],"explanation":["무거운 것부터예요.","상자가 많을수록 무거워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#19','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C18',3,'mc','auto','수평 잡기에서 한 물체는 받침점 가까이, 다른 물체는 자 끝에 놓으면 어떤 문제가 생기나요?',ARRAY['SC3-1-u1-X14','SC3-1-u1-X13','SC3-1-u1-X16']::text[],false,'{"seq":19,"concept":"SC3-1-u1-C18","difficulty":3,"kind":"mc","stem":"수평 잡기에서 한 물체는 받침점 가까이, 다른 물체는 자 끝에 놓으면 어떤 문제가 생기나요?","options":[{"t":"무게를 바르게 비교할 수 없어요","correct":true},{"t":"아무 문제가 없어요","mis":"SC3-1-u1-X14"},{"t":"무거운 쪽이 늘 위로 올라가요","mis":"SC3-1-u1-X13"},{"t":"두 물체의 무게가 같아져요","mis":"SC3-1-u1-X16"}],"explanation":["규칙을 떠올려요.","같은 거리여야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#20','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C26',3,'mc','auto','용수철저울에 물체를 걸었을 때 용수철이 더 많이 늘어난 물체는 어떤가요?',ARRAY['SC3-1-u1-X23','SC3-1-u1-X22']::text[],false,'{"seq":20,"concept":"SC3-1-u1-C26","difficulty":3,"kind":"mc","stem":"용수철저울에 물체를 걸었을 때 용수철이 더 많이 늘어난 물체는 어떤가요?","options":[{"t":"더 무거워요","correct":true},{"t":"더 가벼워요","mis":"SC3-1-u1-X23"},{"t":"무게가 같아요","mis":"SC3-1-u1-X23"},{"t":"알 수 없어요","mis":"SC3-1-u1-X22"}],"explanation":["무거울수록 당겨요.","많이 늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#21','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C30',3,'mc','auto','빗면을 따라 물체를 밀어 올리면 좋은 점은 무엇인가요?',ARRAY['SC3-1-u1-X25','SC3-1-u1-X26','SC3-1-u1-X05']::text[],false,'{"seq":21,"concept":"SC3-1-u1-C30","difficulty":3,"kind":"mc","stem":"빗면을 따라 물체를 밀어 올리면 좋은 점은 무엇인가요?","options":[{"t":"곧장 들어 올릴 때보다 작은 힘이 들어요","correct":true},{"t":"곧장 들 때보다 큰 힘이 들어요","mis":"SC3-1-u1-X25"},{"t":"물체의 무게를 잴 수 있어요","mis":"SC3-1-u1-X26"},{"t":"물체가 저절로 올라가요","mis":"SC3-1-u1-X05"}],"explanation":["경사로를 떠올려요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#22','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C35',3,'mc','auto','학교 현관에 경사로를 만들면 누구에게 특히 도움이 될까요?',ARRAY['SC3-1-u1-X32','SC3-1-u1-X29']::text[],false,'{"seq":22,"concept":"SC3-1-u1-C35","difficulty":3,"kind":"mc","stem":"학교 현관에 경사로를 만들면 누구에게 특히 도움이 될까요?","options":[{"t":"휠체어를 탄 사람과 무거운 수레를 미는 사람","correct":true},{"t":"아무에게도 도움이 안 된다","mis":"SC3-1-u1-X32"},{"t":"종이를 자르는 사람","mis":"SC3-1-u1-X29"},{"t":"병뚜껑을 여는 사람","mis":"SC3-1-u1-X29"}],"explanation":["경사로는 빗면이에요.","바퀴 달린 것을 밀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#23','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C9',4,'mc','auto','친구가 「멈춰 있는 수레도 오래 기다리면 스스로 움직일 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02','SC3-1-u1-X06']::text[],false,'{"seq":23,"concept":"SC3-1-u1-C9","difficulty":4,"kind":"mc","stem":"친구가 「멈춰 있는 수레도 오래 기다리면 스스로 움직일 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「멈춰 있는 물체는 누군가 밀거나 당겨야 움직여.」","correct":true},{"t":"「맞아, 기다리면 움직여.」","mis":"SC3-1-u1-X05"},{"t":"「수레를 바라보면 움직여.」","mis":"SC3-1-u1-X02"},{"t":"「힘은 수레를 멈추게만 해.」","mis":"SC3-1-u1-X06"}],"explanation":["물체는 스스로 못 움직여요.","힘이 필요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#24','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C12',4,'mc','auto','친구가 「수레를 당길 때는 짐을 많이 실어도 힘이 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X10','SC3-1-u1-X09','SC3-1-u1-X01']::text[],false,'{"seq":24,"concept":"SC3-1-u1-C12","difficulty":4,"kind":"mc","stem":"친구가 「수레를 당길 때는 짐을 많이 실어도 힘이 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「당길 때도 짐이 많아 무거울수록 큰 힘이 들어.」","correct":true},{"t":"「맞아, 당길 때는 똑같아.」","mis":"SC3-1-u1-X10"},{"t":"「짐이 많을수록 작은 힘이 들어.」","mis":"SC3-1-u1-X09"},{"t":"「당기는 건 힘이 아니야.」","mis":"SC3-1-u1-X01"}],"explanation":["밀 때와 견줘요.","같아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_a#25','sci',3,1,'u1','','g3_1_sci_u1_review_a','unit_review','SC3-1-u1-C1',4,'essay','teacher','새봄반 일지 ①을 보고 공이 페트병을 넘어뜨린 까닭을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u1-C1","difficulty":4,"kind":"essay","stem":"새봄반 일지 ①을 보고 공이 페트병을 넘어뜨린 까닭을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 손으로 공을 세게 밀어 힘을 주었더니 공이 빠르게 굴러가 페트병에 부딪쳐 넘어뜨렸다. 공은 저절로 굴러간 것이 아니라 손으로 밀어 준 힘 때문에 굴러갔다.","scoring_points":["공을 밀어 힘을 주었다고 썼는가","공이 페트병에 부딪쳐 넘어뜨렸다고 썼는가","저절로가 아니라 힘 때문이라고 친구 가의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","누가 밀었나요?","고쳐 써요."],"asset":{"type":"passage","lines":["페트병 두 개를 세우고 공을 굴려 넘어뜨리는 놀이를 했다.","처음에는 약하게 밀어 공이 페트병까지 가지 못했다.","다음에는 세게 밀어 공이 빠르게 굴러가 페트병이 넘어졌다.","찰흙을 손으로 눌렀더니 납작해졌다.","친구 가 — 「공이 저절로 굴러가서 페트병을 넘어뜨렸어.」"],"title":"새봄반 일지 ① 공 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#1','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C1',1,'ox','auto','새봄반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C1","difficulty":1,"kind":"ox","stem":"새봄반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"손으로 공을 밀어 힘을 주어서 공이 굴러갔기 때문에","correct":true},{"t":"공은 둥글어서 저절로 굴러가기 때문에","mis":"SC3-1-u1-X05"}],"mis":"SC3-1-u1-X05","explanation":["누가 공을 밀었나요?","우리가 밀었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["페트병 두 개를 세우고 공을 굴려 넘어뜨리는 놀이를 했다.","처음에는 약하게 밀어 공이 페트병까지 가지 못했다.","다음에는 세게 밀어 공이 빠르게 굴러가 페트병이 넘어졌다.","찰흙을 손으로 눌렀더니 납작해졌다.","친구 가 — 「공이 저절로 굴러가서 페트병을 넘어뜨렸어.」"],"title":"새봄반 일지 ① 공 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#2','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C8',1,'ox','auto','새봄반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u1-X06']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C8","difficulty":1,"kind":"ox","stem":"새봄반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"굴러오던 공을 잡아 멈춘 것처럼 힘은 멈추게도 하기 때문에","correct":true},{"t":"멈출 때는 힘이 필요 없기 때문에","mis":"SC3-1-u1-X06"}],"mis":"SC3-1-u1-X06","explanation":["둘째 줄을 읽어요.","멈췄어요.","그래서 X예요."],"asset":{"type":"passage","lines":["멈춰 있던 수레를 밀었더니 앞으로 움직였다.","굴러오던 공을 두 손으로 잡았더니 멈췄다.","닫힌 문을 손잡이로 당겨 열었다.","아무도 건드리지 않은 의자는 그대로 있었다.","친구 나 — 「힘은 물체를 움직이게만 해.」"],"title":"새봄반 일지 ② 교실 속 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#3','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C13',1,'ox','auto','새봄반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u1-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C13","difficulty":1,"kind":"ox","stem":"새봄반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"크기가 같아도 책을 많이 넣을수록 무거워 큰 힘이 들기 때문에","correct":true},{"t":"크기가 같으면 무게도 언제나 같기 때문에","mis":"SC3-1-u1-X12"}],"mis":"SC3-1-u1-X12","explanation":["넷째 줄을 읽어요.","㉢이 가장 힘들었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자 · ㉡ 책 2권 상자 · ㉢ 책 5권 상자","먼저 드는 힘을 예상한 뒤 하나씩 밀어 보았다.","㉢을 밀 때 가장 큰 힘이 들었다.","친구 다 — 「크기가 같으니 세 상자 모두 같은 힘이 들 거야.」"],"title":"새봄반 일지 ③ 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#4','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C20',1,'ox','auto','새봄반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u1-X13']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C20","difficulty":1,"kind":"ox","stem":"새봄반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"자는 무거운 쪽으로 기울어 아래로 내려가기 때문에","correct":true},{"t":"자는 가벼운 쪽으로 기울기 때문에","mis":"SC3-1-u1-X13"}],"mis":"SC3-1-u1-X13","explanation":["기운 쪽이 어디인가요?","아래로 내려간 쪽이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["자를 휴지 심 위에 올려 수평을 맞추었다.","같은 거리에 구슬 ㉮와 ㉯를 올렸더니 ㉮ 쪽으로 기울었다.","구슬 ㉯와 ㉰를 같은 거리에 올렸더니 수평을 이루었다.","친구 가 — 「위로 올라간 쪽 구슬이 더 무거워.」"],"title":"새봄반 일지 ④ 수평 잡기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#5','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C23',1,'ox','auto','새봄반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u1-X19']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C23","difficulty":1,"kind":"ox","stem":"새봄반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"손 느낌은 사람마다 달라 저울로 재어야 정확하기 때문에","correct":true},{"t":"손은 저울보다 정확하기 때문에","mis":"SC3-1-u1-X19"}],"mis":"SC3-1-u1-X19","explanation":["첫 줄을 읽어요.","친구마다 달랐어요.","그래서 X예요."],"asset":{"type":"passage","lines":["통조림과 물병을 손으로 들어 보니 친구마다 무거운 것이 달랐다.","전자저울로 재니 통조림 400 g, 물병 550 g이었다.","용수철저울에 가방 고리를 걸었더니 용수철이 늘어났다.","친구 나 — 「손으로 들어 본 게 저울보다 더 정확해.」"],"title":"새봄반 일지 ⑤ 손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#6','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C31',1,'ox','auto','새봄반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u1-X25']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C31","difficulty":1,"kind":"ox","stem":"새봄반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"맨손으로는 꿈쩍 않던 돌을 지레로 들었듯이 도구를 쓰면 작은 힘이 들기 때문에","correct":true},{"t":"도구는 준비하느라 언제나 힘이 더 들기 때문에","mis":"SC3-1-u1-X25"}],"mis":"SC3-1-u1-X25","explanation":["첫째와 둘째 줄을 견줘요.","도구로는 들렸어요.","그래서 X예요."],"asset":{"type":"passage","lines":["무거운 돌을 맨손으로 들려니 꿈쩍도 하지 않았다.","긴 막대를 받침대에 걸치고 막대 끝을 눌렀더니 돌이 들렸다.","무거운 수레는 비스듬한 판자를 따라 밀어 올렸다.","친구 다 — 「도구를 쓰면 힘이 더 들어.」"],"title":"새봄반 일지 ⑥ 무거운 돌 옮기기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#7','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C34',1,'ox','auto','새봄반 일지 ⑦을 보면 도구는 집, 학교, 놀이터 곳곳에 있어요.',ARRAY['SC3-1-u1-X30']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C34","difficulty":1,"kind":"ox","stem":"새봄반 일지 ⑦을 보면 도구는 집, 학교, 놀이터 곳곳에 있어요.","answer":"O","reason_options":[{"t":"가위·계단·시소처럼 가까운 곳에서 도구를 찾았기 때문에","correct":true},{"t":"도구는 공장 같은 특별한 곳에만 있기 때문에","mis":"SC3-1-u1-X30"}],"mis":"SC3-1-u1-X30","explanation":["찾은 곳을 세어 봐요.","세 곳이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["집에서 가위와 병따개를 찾았다.","학교에서 계단과 현관 경사로를 찾았다.","놀이터에서 시소와 미끄럼틀을 찾았다.","모둠 친구들과 찾은 도구를 모아 게시판에 붙였다.","친구 가 — 「도구는 공장에만 있는 줄 알았어.」"],"title":"새봄반 일지 ⑦ 도구 탐정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#8','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C38',1,'ox','auto','새봄반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u1-X33']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C38","difficulty":1,"kind":"ox","stem":"새봄반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"입는 로봇은 사람이 몸에 입어 힘을 더해 주는 기계이기 때문에","correct":true},{"t":"로봇은 모두 사람 없이 혼자 일하기 때문에","mis":"SC3-1-u1-X33"}],"mis":"SC3-1-u1-X33","explanation":["이름을 떠올려요.","입어요.","그래서 X예요."],"asset":{"type":"passage","lines":["공사장 사람이 입는 로봇을 입고 무거운 자재를 들었다.","로봇 없이 들 때보다 작은 힘이 들었다.","병원에서는 환자를 일으킬 때 입는 로봇이 도왔다.","친구 나 — 「입는 로봇은 사람 없이 혼자 일하는 로봇이야.」"],"title":"새봄반 일지 ⑧ 입는 로봇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#9','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C2',2,'ox','auto','공을 세게 찰수록 공은 더 멀리 굴러가요.',ARRAY['SC3-1-u1-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C2","difficulty":2,"kind":"ox","stem":"공을 세게 찰수록 공은 더 멀리 굴러가요.","answer":"O","reason_options":[{"t":"힘을 세게 줄수록 공이 더 빠르고 멀리 가기 때문에","correct":true},{"t":"힘의 세기와 공이 가는 거리는 관계없기 때문에","mis":"SC3-1-u1-X03"}],"mis":"SC3-1-u1-X03","explanation":["축구를 떠올려요.","세게 차면 멀리 가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#10','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C9',2,'ox','auto','멈춰 있는 물체는 힘을 주지 않아도 스스로 움직일 수 있어요.',ARRAY['SC3-1-u1-X05']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C9","difficulty":2,"kind":"ox","stem":"멈춰 있는 물체는 힘을 주지 않아도 스스로 움직일 수 있어요.","answer":"X","reason_options":[{"t":"멈춰 있는 물체는 힘을 주어야 움직이기 때문에","correct":true},{"t":"물체는 움직이고 싶을 때 스스로 움직이기 때문에","mis":"SC3-1-u1-X05"}],"mis":"SC3-1-u1-X05","explanation":["의자를 떠올려요.","그대로 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#11','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C15',2,'ox','auto','너무 무거운 상자는 혼자 무리해서 들지 않고 도움을 받아요.',ARRAY['SC3-1-u1-X08']::text[],false,'{"seq":11,"concept":"SC3-1-u1-C15","difficulty":2,"kind":"ox","stem":"너무 무거운 상자는 혼자 무리해서 들지 않고 도움을 받아요.","answer":"O","reason_options":[{"t":"무리해서 들면 다칠 수 있기 때문에","correct":true},{"t":"무거워도 혼자 드는 것이 언제나 안전하기 때문에","mis":"SC3-1-u1-X08"}],"mis":"SC3-1-u1-X08","explanation":["안전을 떠올려요.","다칠 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#12','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C22',2,'ox','auto','수평인 시소의 오른쪽에 친구가 한 명 더 앉으면 시소는 오른쪽으로 기울어요.',ARRAY['SC3-1-u1-X18']::text[],false,'{"seq":12,"concept":"SC3-1-u1-C22","difficulty":2,"kind":"ox","stem":"수평인 시소의 오른쪽에 친구가 한 명 더 앉으면 시소는 오른쪽으로 기울어요.","answer":"O","reason_options":[{"t":"친구가 더 앉은 오른쪽이 무거워지기 때문에","correct":true},{"t":"사람이 많아진 반대쪽으로 기울기 때문에","mis":"SC3-1-u1-X18"}],"mis":"SC3-1-u1-X18","explanation":["어느 쪽이 무거워졌나요?","오른쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#13','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C28',2,'ox','auto','요리할 때 재료의 무게를 재는 데 저울을 써요.',ARRAY['SC3-1-u1-X24']::text[],false,'{"seq":13,"concept":"SC3-1-u1-C28","difficulty":2,"kind":"ox","stem":"요리할 때 재료의 무게를 재는 데 저울을 써요.","answer":"O","reason_options":[{"t":"재료의 무게를 정확히 맞추기 위해 저울을 쓰기 때문에","correct":true},{"t":"저울은 길이를 재는 데만 쓰기 때문에","mis":"SC3-1-u1-X24"}],"mis":"SC3-1-u1-X24","explanation":["부엌을 떠올려요.","재료를 재요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#14','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C29',2,'ox','auto','시소는 지레를 이용한 도구예요.',ARRAY['SC3-1-u1-X26']::text[],false,'{"seq":14,"concept":"SC3-1-u1-C29","difficulty":2,"kind":"ox","stem":"시소는 지레를 이용한 도구예요.","answer":"O","reason_options":[{"t":"긴 막대의 한 점을 받쳐 물체를 움직이게 하기 때문에","correct":true},{"t":"시소는 비스듬한 면이라 빗면이기 때문에","mis":"SC3-1-u1-X26"}],"mis":"SC3-1-u1-X26","explanation":["시소 모양을 떠올려요.","막대를 받쳤어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#15','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C36',2,'ox','auto','찾은 도구를 친구들과 나누면 더 많은 도구를 알 수 있어요.',ARRAY['SC3-1-u1-X31']::text[],false,'{"seq":15,"concept":"SC3-1-u1-C36","difficulty":2,"kind":"ox","stem":"찾은 도구를 친구들과 나누면 더 많은 도구를 알 수 있어요.","answer":"O","reason_options":[{"t":"친구가 찾은 도구까지 함께 알게 되기 때문에","correct":true},{"t":"나누면 내가 찾은 도구가 사라지기 때문에","mis":"SC3-1-u1-X31"}],"mis":"SC3-1-u1-X31","explanation":["나누면 어떻게 되나요?","더 많아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#16','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C39',2,'ox','auto','입는 로봇을 입으면 무거운 물건도 작은 힘으로 들 수 있어요.',ARRAY['SC3-1-u1-X34']::text[],false,'{"seq":16,"concept":"SC3-1-u1-C39","difficulty":2,"kind":"ox","stem":"입는 로봇을 입으면 무거운 물건도 작은 힘으로 들 수 있어요.","answer":"O","reason_options":[{"t":"입는 로봇이 사람의 힘을 더해 주기 때문에","correct":true},{"t":"입는 로봇을 입으면 힘이 더 들기 때문에","mis":"SC3-1-u1-X34"}],"mis":"SC3-1-u1-X34","explanation":["로봇이 하는 일이에요.","힘을 더해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#17','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C2',3,'ox','auto','페트병을 더 멀리 놓았다면 공을 더 세게 밀어야 넘어뜨리기 쉬워요.',ARRAY['SC3-1-u1-X03']::text[],false,'{"seq":17,"concept":"SC3-1-u1-C2","difficulty":3,"kind":"ox","stem":"페트병을 더 멀리 놓았다면 공을 더 세게 밀어야 넘어뜨리기 쉬워요.","answer":"O","reason_options":[{"t":"세게 밀수록 공이 더 멀리 굴러가기 때문에","correct":true},{"t":"공은 힘의 세기와 상관없이 늘 같은 거리만 가기 때문에","mis":"SC3-1-u1-X03"}],"mis":"SC3-1-u1-X03","explanation":["멀리 보내려면요?","세게 밀어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#18','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C11',3,'ox','auto','크기가 같은 상자라도 안에 든 물건이 많을수록 밀 때 큰 힘이 들어요.',ARRAY['SC3-1-u1-X12']::text[],false,'{"seq":18,"concept":"SC3-1-u1-C11","difficulty":3,"kind":"ox","stem":"크기가 같은 상자라도 안에 든 물건이 많을수록 밀 때 큰 힘이 들어요.","answer":"O","reason_options":[{"t":"물건이 많을수록 무거워지기 때문에","correct":true},{"t":"상자 크기만 같으면 드는 힘도 같기 때문에","mis":"SC3-1-u1-X12"}],"mis":"SC3-1-u1-X12","explanation":["크기보다 무게예요.","많이 들면 무거워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#19','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C21',3,'ox','auto','세 물체의 무게를 비교할 때는 두 개씩 차례로 수평대에 올려 비교할 수 있어요.',ARRAY['SC3-1-u1-X17']::text[],false,'{"seq":19,"concept":"SC3-1-u1-C21","difficulty":3,"kind":"ox","stem":"세 물체의 무게를 비교할 때는 두 개씩 차례로 수평대에 올려 비교할 수 있어요.","answer":"O","reason_options":[{"t":"두 개씩 비교한 결과를 이으면 가장 무거운 것을 찾을 수 있기 때문에","correct":true},{"t":"세 물체를 한꺼번에 한쪽에 올려야 하기 때문에","mis":"SC3-1-u1-X17"}],"mis":"SC3-1-u1-X17","explanation":["사과·배·귤을 떠올려요.","둘씩 견줬어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#20','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C23',3,'ox','auto','모둠 친구들이 손으로 들어 정한 무게 차례가 서로 다른 것은 이상한 일이 아니에요.',ARRAY['SC3-1-u1-X19']::text[],false,'{"seq":20,"concept":"SC3-1-u1-C23","difficulty":3,"kind":"ox","stem":"모둠 친구들이 손으로 들어 정한 무게 차례가 서로 다른 것은 이상한 일이 아니에요.","answer":"O","reason_options":[{"t":"사람마다 무게를 느끼는 느낌이 다르기 때문에","correct":true},{"t":"손으로 들면 누구나 똑같이 느끼기 때문에","mis":"SC3-1-u1-X19"}],"mis":"SC3-1-u1-X19","explanation":["손 느낌을 떠올려요.","사람마다 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#21','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C32',3,'ox','auto','가위와 병따개는 빗면을 이용한 도구예요.',ARRAY['SC3-1-u1-X27']::text[],false,'{"seq":21,"concept":"SC3-1-u1-C32","difficulty":3,"kind":"ox","stem":"가위와 병따개는 빗면을 이용한 도구예요.","answer":"X","reason_options":[{"t":"가위와 병따개는 막대를 받쳐 쓰는 지레를 이용한 도구이기 때문에","correct":true},{"t":"손에 쥐고 쓰는 도구는 모두 빗면이기 때문에","mis":"SC3-1-u1-X27"}],"mis":"SC3-1-u1-X27","explanation":["비스듬한가요?","아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#22','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C37',3,'ox','auto','지레와 빗면 같은 도구 덕분에 우리 생활이 더 편해졌어요.',ARRAY['SC3-1-u1-X32']::text[],false,'{"seq":22,"concept":"SC3-1-u1-C37","difficulty":3,"kind":"ox","stem":"지레와 빗면 같은 도구 덕분에 우리 생활이 더 편해졌어요.","answer":"O","reason_options":[{"t":"무거운 일을 작은 힘으로 할 수 있게 되었기 때문에","correct":true},{"t":"도구는 생활과 아무 관계가 없기 때문에","mis":"SC3-1-u1-X32"}],"mis":"SC3-1-u1-X32","explanation":["도구가 하는 일이에요.","힘을 줄여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#23','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C20',4,'mc','auto','친구가 「수평대에서 위로 올라간 쪽이 더 무거운 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X12','SC3-1-u1-X16']::text[],false,'{"seq":23,"concept":"SC3-1-u1-C20","difficulty":4,"kind":"mc","stem":"친구가 「수평대에서 위로 올라간 쪽이 더 무거운 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무거운 쪽으로 기울어 아래로 내려가니, 내려간 쪽이 더 무거워.」","correct":true},{"t":"「맞아, 올라간 쪽이 무거워.」","mis":"SC3-1-u1-X13"},{"t":"「크기가 큰 쪽이 무거워.」","mis":"SC3-1-u1-X12"},{"t":"「기울어지면 무게를 알 수 없어.」","mis":"SC3-1-u1-X16"}],"explanation":["시소를 떠올려요.","내려간 쪽이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#24','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C22',4,'mc','auto','친구가 「수평인 시소에서 한쪽 친구가 내리면 그대로 수평이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X18','SC3-1-u1-X13']::text[],false,'{"seq":24,"concept":"SC3-1-u1-C22","difficulty":4,"kind":"mc","stem":"친구가 「수평인 시소에서 한쪽 친구가 내리면 그대로 수평이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「친구가 내린 쪽이 가벼워져서 반대쪽으로 기울어.」","correct":true},{"t":"「맞아, 그대로 수평이야.」","mis":"SC3-1-u1-X18"},{"t":"「친구가 내린 쪽으로 기울어.」","mis":"SC3-1-u1-X13"},{"t":"「시소는 가벼운 쪽으로 기울어.」","mis":"SC3-1-u1-X13"}],"explanation":["어느 쪽이 가벼워졌나요?","무거운 쪽으로 기울어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_b#25','sci',3,1,'u1','','g3_1_sci_u1_review_b','unit_review','SC3-1-u1-C20',4,'essay','teacher','새봄반 일지 ④를 보고 구슬 ㉮, ㉯, ㉰의 무게를 비교해 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u1-C20","difficulty":4,"kind":"essay","stem":"새봄반 일지 ④를 보고 구슬 ㉮, ㉯, ㉰의 무게를 비교해 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: ㉮가 ㉯보다 무겁고, ㉯와 ㉰는 무게가 같다. 그래서 ㉮가 가장 무겁다. 자는 무거운 쪽으로 기울어 아래로 내려가므로 내려간 쪽 구슬이 더 무겁다.","scoring_points":["㉮가 ㉯보다 무겁다고 썼는가","㉯와 ㉰의 무게가 같다고 썼는가","내려간 쪽이 무겁다고 친구 가의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","기운 쪽을 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["자를 휴지 심 위에 올려 수평을 맞추었다.","같은 거리에 구슬 ㉮와 ㉯를 올렸더니 ㉮ 쪽으로 기울었다.","구슬 ㉯와 ㉰를 같은 거리에 올렸더니 수평을 이루었다.","친구 가 — 「위로 올라간 쪽 구슬이 더 무거워.」"],"title":"새봄반 일지 ④ 수평 잡기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#1','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C4',1,'mc','auto','새봄반 일지 ①에서 찰흙을 손으로 누른 뒤 일어난 일은 무엇인가요?',ARRAY['SC3-1-u1-X04','SC3-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄반 일지 ①에서 찰흙을 손으로 누른 뒤 일어난 일은 무엇인가요?","options":[{"t":"모양이 변했다","correct":true},{"t":"아무 변화가 없었다","mis":"SC3-1-u1-X04"},{"t":"색깔이 바뀌었다","mis":"SC3-1-u1-X04"},{"t":"저절로 굴러갔다","mis":"SC3-1-u1-X05"}],"explanation":["넷째 줄을 읽어요.","납작해졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["페트병 두 개를 세우고 공을 굴려 넘어뜨리는 놀이를 했다.","처음에는 약하게 밀어 공이 페트병까지 가지 못했다.","다음에는 세게 밀어 공이 빠르게 굴러가 페트병이 넘어졌다.","찰흙을 손으로 눌렀더니 납작해졌다.","친구 가 — 「공이 저절로 굴러가서 페트병을 넘어뜨렸어.」"],"title":"새봄반 일지 ① 공 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#2','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C9',1,'mc','auto','새봄반 일지 ②에서 의자가 그대로 있었던 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X05','SC3-1-u1-X02','SC3-1-u1-X04']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C9","difficulty":1,"kind":"mc","stem":"새봄반 일지 ②에서 의자가 그대로 있었던 까닭은 무엇인가요?","options":[{"t":"아무도 의자에 힘을 주지 않았기 때문에","correct":true},{"t":"의자가 움직이기 싫어서","mis":"SC3-1-u1-X05"},{"t":"의자를 바라보지 않아서","mis":"SC3-1-u1-X02"},{"t":"의자 색깔 때문에","mis":"SC3-1-u1-X04"}],"explanation":["넷째 줄을 읽어요.","건드리지 않았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["멈춰 있던 수레를 밀었더니 앞으로 움직였다.","굴러오던 공을 두 손으로 잡았더니 멈췄다.","닫힌 문을 손잡이로 당겨 열었다.","아무도 건드리지 않은 의자는 그대로 있었다.","친구 나 — 「힘은 물체를 움직이게만 해.」"],"title":"새봄반 일지 ② 교실 속 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#3','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C14',1,'mc','auto','새봄반 일지 ③에서 상자를 밀기 전에 먼저 한 일은 무엇인가요?',ARRAY['SC3-1-u1-X11','SC3-1-u1-X08']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C14","difficulty":1,"kind":"mc","stem":"새봄반 일지 ③에서 상자를 밀기 전에 먼저 한 일은 무엇인가요?","options":[{"t":"드는 힘을 예상했다","correct":true},{"t":"결과를 발표했다","mis":"SC3-1-u1-X11"},{"t":"상자를 던졌다","mis":"SC3-1-u1-X08"},{"t":"아무것도 하지 않았다","mis":"SC3-1-u1-X11"}],"explanation":["셋째 줄을 읽어요.","먼저 한 일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자 · ㉡ 책 2권 상자 · ㉢ 책 5권 상자","먼저 드는 힘을 예상한 뒤 하나씩 밀어 보았다.","㉢을 밀 때 가장 큰 힘이 들었다.","친구 다 — 「크기가 같으니 세 상자 모두 같은 힘이 들 거야.」"],"title":"새봄반 일지 ③ 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#4','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C19',1,'mc','auto','새봄반 일지 ④에서 ㉯와 ㉰의 무게는 어떤가요?',ARRAY['SC3-1-u1-X16','SC3-1-u1-X15']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C19","difficulty":1,"kind":"mc","stem":"새봄반 일지 ④에서 ㉯와 ㉰의 무게는 어떤가요?","options":[{"t":"서로 같다","correct":true},{"t":"㉯가 더 무겁다","mis":"SC3-1-u1-X16"},{"t":"㉰가 더 무겁다","mis":"SC3-1-u1-X16"},{"t":"알 수 없다","mis":"SC3-1-u1-X15"}],"explanation":["셋째 줄을 읽어요.","수평이었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["자를 휴지 심 위에 올려 수평을 맞추었다.","같은 거리에 구슬 ㉮와 ㉯를 올렸더니 ㉮ 쪽으로 기울었다.","구슬 ㉯와 ㉰를 같은 거리에 올렸더니 수평을 이루었다.","친구 가 — 「위로 올라간 쪽 구슬이 더 무거워.」"],"title":"새봄반 일지 ④ 수평 잡기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#5','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C25',1,'mc','auto','새봄반 일지 ⑤의 「400 g」을 바르게 읽은 것은 무엇인가요?',ARRAY['SC3-1-u1-X21']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C25","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑤의 「400 g」을 바르게 읽은 것은 무엇인가요?","options":[{"t":"사백 그램","correct":true},{"t":"사백 센티미터","mis":"SC3-1-u1-X21"},{"t":"사백 리터","mis":"SC3-1-u1-X21"},{"t":"사백 분","mis":"SC3-1-u1-X21"}],"explanation":["g은 무게 단위예요.","그램이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["통조림과 물병을 손으로 들어 보니 친구마다 무거운 것이 달랐다.","전자저울로 재니 통조림 400 g, 물병 550 g이었다.","용수철저울에 가방 고리를 걸었더니 용수철이 늘어났다.","친구 나 — 「손으로 들어 본 게 저울보다 더 정확해.」"],"title":"새봄반 일지 ⑤ 손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#6','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C30',1,'mc','auto','새봄반 일지 ⑥에서 수레를 밀어 올린 비스듬한 판자는 무엇인가요?',ARRAY['SC3-1-u1-X26','SC3-1-u1-X27']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C30","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑥에서 수레를 밀어 올린 비스듬한 판자는 무엇인가요?","options":[{"t":"빗면","correct":true},{"t":"지레","mis":"SC3-1-u1-X26"},{"t":"시소","mis":"SC3-1-u1-X27"},{"t":"저울","mis":"SC3-1-u1-X26"}],"explanation":["셋째 줄을 읽어요.","비스듬해요.","빗면이에요."],"asset":{"type":"passage","lines":["무거운 돌을 맨손으로 들려니 꿈쩍도 하지 않았다.","긴 막대를 받침대에 걸치고 막대 끝을 눌렀더니 돌이 들렸다.","무거운 수레는 비스듬한 판자를 따라 밀어 올렸다.","친구 다 — 「도구를 쓰면 힘이 더 들어.」"],"title":"새봄반 일지 ⑥ 무거운 돌 옮기기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#7','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C36',1,'mc','auto','새봄반 일지 ⑦에서 찾은 도구를 게시판에 모아 붙이면 좋은 점은 무엇인가요?',ARRAY['SC3-1-u1-X31']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C36","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑦에서 찾은 도구를 게시판에 모아 붙이면 좋은 점은 무엇인가요?","options":[{"t":"서로 찾은 도구를 나누어 더 많이 알 수 있다","correct":true},{"t":"도구가 줄어든다","mis":"SC3-1-u1-X31"},{"t":"아무 도움이 안 된다","mis":"SC3-1-u1-X31"},{"t":"혼자만 알 수 있다","mis":"SC3-1-u1-X31"}],"explanation":["넷째 줄을 읽어요.","모았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["집에서 가위와 병따개를 찾았다.","학교에서 계단과 현관 경사로를 찾았다.","놀이터에서 시소와 미끄럼틀을 찾았다.","모둠 친구들과 찾은 도구를 모아 게시판에 붙였다.","친구 가 — 「도구는 공장에만 있는 줄 알았어.」"],"title":"새봄반 일지 ⑦ 도구 탐정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#8','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C40',1,'mc','auto','새봄반 일지 ⑧에서 입는 로봇이 도운 곳을 모두 모은 것은 무엇인가요?',ARRAY['SC3-1-u1-X35']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C40","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑧에서 입는 로봇이 도운 곳을 모두 모은 것은 무엇인가요?","options":[{"t":"공사장, 병원","correct":true},{"t":"도서관, 미술실","mis":"SC3-1-u1-X35"},{"t":"공사장, 도서관","mis":"SC3-1-u1-X35"},{"t":"병원, 침실","mis":"SC3-1-u1-X35"}],"explanation":["첫째와 셋째 줄이에요.","두 곳이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["공사장 사람이 입는 로봇을 입고 무거운 자재를 들었다.","로봇 없이 들 때보다 작은 힘이 들었다.","병원에서는 환자를 일으킬 때 입는 로봇이 도왔다.","친구 나 — 「입는 로봇은 사람 없이 혼자 일하는 로봇이야.」"],"title":"새봄반 일지 ⑧ 입는 로봇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
