INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#17','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C8',3,'mc','auto','골키퍼가 날아오는 공을 잡을 때 힘이 한 일은 무엇인가요?',ARRAY['SC3-1-u1-X07','SC3-1-u1-X06','SC3-1-u1-X05']::text[],false,'{"seq":17,"concept":"SC3-1-u1-C8","difficulty":3,"kind":"mc","stem":"골키퍼가 날아오는 공을 잡을 때 힘이 한 일은 무엇인가요?","options":[{"t":"움직이던 공을 멈추게 했다","correct":true},{"t":"공을 더 빨리 날아가게 했다","mis":"SC3-1-u1-X07"},{"t":"아무 일도 하지 않았다","mis":"SC3-1-u1-X06"},{"t":"공이 저절로 멈췄다","mis":"SC3-1-u1-X05"}],"explanation":["공을 잡았어요.","섰어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#18','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C14',3,'mc','auto','두 상자를 밀어 본 결과가 예상과 달랐을 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-1-u1-X11']::text[],false,'{"seq":18,"concept":"SC3-1-u1-C14","difficulty":3,"kind":"mc","stem":"두 상자를 밀어 본 결과가 예상과 달랐을 때 알맞은 태도는 무엇인가요?","options":[{"t":"실제로 느낀 결과를 그대로 적고 까닭을 생각해요","correct":true},{"t":"예상대로 나왔다고 고쳐 적어요","mis":"SC3-1-u1-X11"},{"t":"결과를 지우고 다시는 하지 않아요","mis":"SC3-1-u1-X11"},{"t":"친구 결과를 그대로 베껴요","mis":"SC3-1-u1-X11"}],"explanation":["결과는 있는 그대로예요.","까닭을 생각해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#19','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C20',3,'mc','auto','시소에 탄 두 사람 가운데 아래로 내려간 쪽이 더 무거운 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X12','SC3-1-u1-X16']::text[],false,'{"seq":19,"concept":"SC3-1-u1-C20","difficulty":3,"kind":"mc","stem":"시소에 탄 두 사람 가운데 아래로 내려간 쪽이 더 무거운 까닭은 무엇인가요?","options":[{"t":"무거운 쪽으로 기울기 때문에","correct":true},{"t":"가벼운 쪽으로 기울기 때문에","mis":"SC3-1-u1-X13"},{"t":"키가 큰 쪽으로 기울기 때문에","mis":"SC3-1-u1-X12"},{"t":"시소는 아무렇게나 기울기 때문에","mis":"SC3-1-u1-X16"}],"explanation":["수평 잡기와 같아요.","무거운 쪽이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#20','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C28',3,'mc','auto','다음 가운데 저울이 꼭 필요한 일은 무엇인가요?',ARRAY['SC3-1-u1-X24']::text[],false,'{"seq":20,"concept":"SC3-1-u1-C28","difficulty":3,"kind":"mc","stem":"다음 가운데 저울이 꼭 필요한 일은 무엇인가요?","options":[{"t":"태권도 선수의 몸무게를 재어 체급을 나누기","correct":true},{"t":"친구와 줄넘기하기","mis":"SC3-1-u1-X24"},{"t":"하늘의 구름 세기","mis":"SC3-1-u1-X24"},{"t":"책상 길이 재기","mis":"SC3-1-u1-X24"}],"explanation":["무게를 재는 일이에요.","몸무게예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#21','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C29',3,'mc','auto','긴 막대를 받침대에 걸치고 한쪽 끝을 눌러 무거운 돌을 들었어요. 이용한 도구와 드는 힘을 바르게 말한 것은 무엇인가요?',ARRAY['SC3-1-u1-X26','SC3-1-u1-X25']::text[],false,'{"seq":21,"concept":"SC3-1-u1-C29","difficulty":3,"kind":"mc","stem":"긴 막대를 받침대에 걸치고 한쪽 끝을 눌러 무거운 돌을 들었어요. 이용한 도구와 드는 힘을 바르게 말한 것은 무엇인가요?","options":[{"t":"지레 — 맨손보다 작은 힘","correct":true},{"t":"빗면 — 맨손보다 작은 힘","mis":"SC3-1-u1-X26"},{"t":"지레 — 맨손보다 큰 힘","mis":"SC3-1-u1-X25"},{"t":"저울 — 맨손과 같은 힘","mis":"SC3-1-u1-X26"}],"explanation":["막대를 받쳤어요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#22','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C40',3,'mc','auto','입는 로봇이 필요한 사람으로 가장 알맞은 것은 누구인가요?',ARRAY['SC3-1-u1-X35']::text[],false,'{"seq":22,"concept":"SC3-1-u1-C40","difficulty":3,"kind":"mc","stem":"입는 로봇이 필요한 사람으로 가장 알맞은 것은 누구인가요?","options":[{"t":"무거운 자재를 하루 종일 드는 공사장 사람","correct":true},{"t":"조용히 책을 읽는 사람","mis":"SC3-1-u1-X35"},{"t":"그림을 그리는 사람","mis":"SC3-1-u1-X35"},{"t":"잠을 자는 사람","mis":"SC3-1-u1-X35"}],"explanation":["힘든 일을 하는 사람이에요.","무거운 것을 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#23','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C24',4,'mc','auto','친구가 「저울 대신 손으로 들어 보는 게 더 빠르고 정확해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X19','SC3-1-u1-X20','SC3-1-u1-X21']::text[],false,'{"seq":23,"concept":"SC3-1-u1-C24","difficulty":4,"kind":"mc","stem":"친구가 「저울 대신 손으로 들어 보는 게 더 빠르고 정확해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「손 느낌은 사람마다 달라서, 정확히 비교하려면 저울을 써야 해.」","correct":true},{"t":"「맞아, 손이 더 정확해.」","mis":"SC3-1-u1-X19"},{"t":"「저울도 사람마다 숫자가 달라.」","mis":"SC3-1-u1-X20"},{"t":"「무게는 cm로 재야 해.」","mis":"SC3-1-u1-X21"}],"explanation":["손 느낌을 떠올려요.","사람마다 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#24','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C36',4,'mc','auto','친구가 「도구 찾기는 혼자 하는 게 제일 좋아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X31','SC3-1-u1-X30','SC3-1-u1-X32']::text[],false,'{"seq":24,"concept":"SC3-1-u1-C36","difficulty":4,"kind":"mc","stem":"친구가 「도구 찾기는 혼자 하는 게 제일 좋아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「친구와 찾은 도구를 나누면 더 많은 도구를 알 수 있어.」","correct":true},{"t":"「맞아, 혼자가 좋아.」","mis":"SC3-1-u1-X31"},{"t":"「도구는 공장에만 있어서 찾을 수 없어.」","mis":"SC3-1-u1-X30"},{"t":"「도구는 생활과 관계없어.」","mis":"SC3-1-u1-X32"}],"explanation":["게시판을 떠올려요.","나누면 많아져요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_c#25','sci',3,1,'u1','','g3_1_sci_u1_review_c','unit_review','SC3-1-u1-C24',4,'essay','teacher','새봄반 일지 ⑤를 보고 통조림과 물병 가운데 더 무거운 것을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u1-C24","difficulty":4,"kind":"essay","stem":"새봄반 일지 ⑤를 보고 통조림과 물병 가운데 더 무거운 것을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 물병이 550 g으로 통조림 400 g보다 더 무겁다. 손으로 들면 사람마다 느낌이 달라 정확하지 않으므로, 무게를 정확히 비교하려면 저울을 써야 한다.","scoring_points":["물병이 더 무겁다고 썼는가","저울의 숫자를 근거로 썼는가","손은 사람마다 달라 저울을 써야 한다고 친구 나의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","저울 숫자를 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["통조림과 물병을 손으로 들어 보니 친구마다 무거운 것이 달랐다.","전자저울로 재니 통조림 400 g, 물병 550 g이었다.","용수철저울에 가방 고리를 걸었더니 용수철이 늘어났다.","친구 나 — 「손으로 들어 본 게 저울보다 더 정확해.」"],"title":"새봄반 일지 ⑤ 손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#1','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C3',1,'mc','auto','새봄반 일지 ①에서 공을 굴린 힘은 무엇인가요?',ARRAY['SC3-1-u1-X01','SC3-1-u1-X02','SC3-1-u1-X37']::text[],false,'{"seq":1,"concept":"SC3-1-u1-C3","difficulty":1,"kind":"mc","stem":"새봄반 일지 ①에서 공을 굴린 힘은 무엇인가요?","options":[{"t":"미는 힘","correct":true},{"t":"당기는 힘","mis":"SC3-1-u1-X01"},{"t":"바라보는 힘","mis":"SC3-1-u1-X02"},{"t":"눈에 보이는 힘 덩어리","mis":"SC3-1-u1-X37"}],"explanation":["공을 어떻게 했나요?","밀었어요.","미는 힘이에요."],"asset":{"type":"passage","lines":["페트병 두 개를 세우고 공을 굴려 넘어뜨리는 놀이를 했다.","처음에는 약하게 밀어 공이 페트병까지 가지 못했다.","다음에는 세게 밀어 공이 빠르게 굴러가 페트병이 넘어졌다.","찰흙을 손으로 눌렀더니 납작해졌다.","친구 가 — 「공이 저절로 굴러가서 페트병을 넘어뜨렸어.」"],"title":"새봄반 일지 ① 공 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#2','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C6',1,'mc','auto','새봄반 일지 ②에서 당기는 힘이 쓰인 것은 무엇인가요?',ARRAY['SC3-1-u1-X01','SC3-1-u1-X07','SC3-1-u1-X02']::text[],false,'{"seq":2,"concept":"SC3-1-u1-C6","difficulty":1,"kind":"mc","stem":"새봄반 일지 ②에서 당기는 힘이 쓰인 것은 무엇인가요?","options":[{"t":"닫힌 문을 손잡이로 당겨 연 일","correct":true},{"t":"수레를 민 일","mis":"SC3-1-u1-X01"},{"t":"공을 잡은 일","mis":"SC3-1-u1-X07"},{"t":"의자가 그대로 있던 일","mis":"SC3-1-u1-X02"}],"explanation":["셋째 줄을 읽어요.","당겨 열었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["멈춰 있던 수레를 밀었더니 앞으로 움직였다.","굴러오던 공을 두 손으로 잡았더니 멈췄다.","닫힌 문을 손잡이로 당겨 열었다.","아무도 건드리지 않은 의자는 그대로 있었다.","친구 나 — 「힘은 물체를 움직이게만 해.」"],"title":"새봄반 일지 ② 교실 속 힘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#3','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C13',1,'mc','auto','새봄반 일지 ③에서 밀 때 큰 힘이 드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X09','SC3-1-u1-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u1-C13","difficulty":1,"kind":"mc","stem":"새봄반 일지 ③에서 밀 때 큰 힘이 드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"㉢ → ㉡ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"SC3-1-u1-X09"},{"t":"㉡ → ㉢ → ㉠","mis":"SC3-1-u1-X09"},{"t":"세 상자 모두 같다","mis":"SC3-1-u1-X12"}],"explanation":["책이 많은 상자부터예요.","㉢이 가장 무거워요.","첫 번째예요."],"asset":{"type":"passage","lines":["크기가 같은 상자 세 개를 준비했다.","㉠ 빈 상자 · ㉡ 책 2권 상자 · ㉢ 책 5권 상자","먼저 드는 힘을 예상한 뒤 하나씩 밀어 보았다.","㉢을 밀 때 가장 큰 힘이 들었다.","친구 다 — 「크기가 같으니 세 상자 모두 같은 힘이 들 거야.」"],"title":"새봄반 일지 ③ 상자 밀기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#4','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C18',1,'mc','auto','새봄반 일지 ④에서 구슬을 같은 거리에 올린 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X14','SC3-1-u1-X08']::text[],false,'{"seq":4,"concept":"SC3-1-u1-C18","difficulty":1,"kind":"mc","stem":"새봄반 일지 ④에서 구슬을 같은 거리에 올린 까닭은 무엇인가요?","options":[{"t":"무게를 바르게 비교하기 위해","correct":true},{"t":"보기에 예뻐서","mis":"SC3-1-u1-X14"},{"t":"거리는 아무 상관이 없어서","mis":"SC3-1-u1-X14"},{"t":"구슬을 굴려 놀려고","mis":"SC3-1-u1-X08"}],"explanation":["수평 잡기 규칙이에요.","바르게 견줘요.","첫 번째예요."],"asset":{"type":"passage","lines":["자를 휴지 심 위에 올려 수평을 맞추었다.","같은 거리에 구슬 ㉮와 ㉯를 올렸더니 ㉮ 쪽으로 기울었다.","구슬 ㉯와 ㉰를 같은 거리에 올렸더니 수평을 이루었다.","친구 가 — 「위로 올라간 쪽 구슬이 더 무거워.」"],"title":"새봄반 일지 ④ 수평 잡기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#5','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C26',1,'mc','auto','새봄반 일지 ⑤에서 가방 고리를 건 용수철저울은 무게를 어떻게 알려 주나요?',ARRAY['SC3-1-u1-X22','SC3-1-u1-X23']::text[],false,'{"seq":5,"concept":"SC3-1-u1-C26","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑤에서 가방 고리를 건 용수철저울은 무게를 어떻게 알려 주나요?","options":[{"t":"용수철이 늘어난 눈금으로 알려 줘요","correct":true},{"t":"숫자 화면으로 알려 줘요","mis":"SC3-1-u1-X22"},{"t":"소리로 알려 줘요","mis":"SC3-1-u1-X22"},{"t":"용수철이 짧아져서 알려 줘요","mis":"SC3-1-u1-X23"}],"explanation":["셋째 줄을 읽어요.","늘어났어요.","첫 번째예요."],"asset":{"type":"passage","lines":["통조림과 물병을 손으로 들어 보니 친구마다 무거운 것이 달랐다.","전자저울로 재니 통조림 400 g, 물병 550 g이었다.","용수철저울에 가방 고리를 걸었더니 용수철이 늘어났다.","친구 나 — 「손으로 들어 본 게 저울보다 더 정확해.」"],"title":"새봄반 일지 ⑤ 손과 저울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#6','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C33',1,'mc','auto','새봄반 일지 ⑥처럼 무거운 돌을 옮길 때 알맞은 생각은 무엇인가요?',ARRAY['SC3-1-u1-X28','SC3-1-u1-X05','SC3-1-u1-X29']::text[],false,'{"seq":6,"concept":"SC3-1-u1-C33","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑥처럼 무거운 돌을 옮길 때 알맞은 생각은 무엇인가요?","options":[{"t":"도구를 이용하거나 여럿이 힘을 합친다","correct":true},{"t":"혼자 맨손으로만 든다","mis":"SC3-1-u1-X28"},{"t":"돌이 저절로 움직이기를 기다린다","mis":"SC3-1-u1-X05"},{"t":"돌을 발로 찬다","mis":"SC3-1-u1-X29"}],"explanation":["맨손으로는 안 됐어요.","도구나 친구예요.","첫 번째예요."],"asset":{"type":"passage","lines":["무거운 돌을 맨손으로 들려니 꿈쩍도 하지 않았다.","긴 막대를 받침대에 걸치고 막대 끝을 눌렀더니 돌이 들렸다.","무거운 수레는 비스듬한 판자를 따라 밀어 올렸다.","친구 다 — 「도구를 쓰면 힘이 더 들어.」"],"title":"새봄반 일지 ⑥ 무거운 돌 옮기기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#7','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C35',1,'mc','auto','새봄반 일지 ⑦에서 휠체어가 건물에 쉽게 들어가도록 돕는 도구는 무엇인가요?',ARRAY['SC3-1-u1-X29']::text[],false,'{"seq":7,"concept":"SC3-1-u1-C35","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑦에서 휠체어가 건물에 쉽게 들어가도록 돕는 도구는 무엇인가요?","options":[{"t":"현관 경사로","correct":true},{"t":"가위","mis":"SC3-1-u1-X29"},{"t":"병따개","mis":"SC3-1-u1-X29"},{"t":"시소","mis":"SC3-1-u1-X29"}],"explanation":["비스듬한 길이에요.","학교 현관에 있어요.","경사로예요."],"asset":{"type":"passage","lines":["집에서 가위와 병따개를 찾았다.","학교에서 계단과 현관 경사로를 찾았다.","놀이터에서 시소와 미끄럼틀을 찾았다.","모둠 친구들과 찾은 도구를 모아 게시판에 붙였다.","친구 가 — 「도구는 공장에만 있는 줄 알았어.」"],"title":"새봄반 일지 ⑦ 도구 탐정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#8','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C41',1,'mc','auto','새봄반 일지 ⑧의 입는 로봇은 어떤 점에서 지레·빗면과 닮았나요?',ARRAY['SC3-1-u1-X36','SC3-1-u1-X34','SC3-1-u1-X26']::text[],false,'{"seq":8,"concept":"SC3-1-u1-C41","difficulty":1,"kind":"mc","stem":"새봄반 일지 ⑧의 입는 로봇은 어떤 점에서 지레·빗면과 닮았나요?","options":[{"t":"무거운 물체를 작은 힘으로 들게 돕는다","correct":true},{"t":"무게를 숫자로 알려 준다","mis":"SC3-1-u1-X36"},{"t":"힘을 더 많이 들게 한다","mis":"SC3-1-u1-X34"},{"t":"비스듬한 면으로 되어 있다","mis":"SC3-1-u1-X26"}],"explanation":["도구가 하는 일이에요.","작은 힘이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["공사장 사람이 입는 로봇을 입고 무거운 자재를 들었다.","로봇 없이 들 때보다 작은 힘이 들었다.","병원에서는 환자를 일으킬 때 입는 로봇이 도왔다.","친구 나 — 「입는 로봇은 사람 없이 혼자 일하는 로봇이야.」"],"title":"새봄반 일지 ⑧ 입는 로봇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#9','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C5',2,'mc','auto','공 놀이를 안전하게 하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC3-1-u1-C5","difficulty":2,"kind":"mc","stem":"공 놀이를 안전하게 하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"주변에 친구가 없는지 살피고 공을 굴려요","correct":true},{"t":"친구 얼굴 쪽으로 공을 던져요","mis":"SC3-1-u1-X08"},{"t":"페트병을 발로 차 날려요","mis":"SC3-1-u1-X08"},{"t":"복도에서 공을 세게 차요","mis":"SC3-1-u1-X08"}],"explanation":["다치지 않아야 해요.","주변을 살펴요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#10','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C7',2,'mc','auto','보드를 발로 밀어 출발할 때와 날아오는 공을 받을 때 힘이 한 일을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u1-X07','SC3-1-u1-X06','SC3-1-u1-X04']::text[],false,'{"seq":10,"concept":"SC3-1-u1-C7","difficulty":2,"kind":"mc","stem":"보드를 발로 밀어 출발할 때와 날아오는 공을 받을 때 힘이 한 일을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"보드 — 움직이게 · 공 — 멈추게","correct":true},{"t":"보드 — 멈추게 · 공 — 움직이게","mis":"SC3-1-u1-X07"},{"t":"보드 — 움직이게 · 공 — 움직이게","mis":"SC3-1-u1-X06"},{"t":"보드 — 아무 일 없음 · 공 — 아무 일 없음","mis":"SC3-1-u1-X04"}],"explanation":["처음과 나중을 봐요.","출발과 받기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#11','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C14',2,'mc','auto','상자를 밀어 본 뒤 예상과 실제를 비교하는 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X11']::text[],false,'{"seq":11,"concept":"SC3-1-u1-C14","difficulty":2,"kind":"mc","stem":"상자를 밀어 본 뒤 예상과 실제를 비교하는 까닭은 무엇인가요?","options":[{"t":"내 생각이 맞았는지 직접 확인하려고","correct":true},{"t":"예상만 하면 끝나서","mis":"SC3-1-u1-X11"},{"t":"친구를 이기려고","mis":"SC3-1-u1-X11"},{"t":"상자를 꾸미려고","mis":"SC3-1-u1-X11"}],"explanation":["탐구의 마지막이에요.","확인해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#12','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C21',2,'mc','auto','귤과 배를 비교하니 배 쪽으로, 배와 사과를 비교하니 배 쪽으로 기울었어요. 가장 무거운 과일은 무엇인가요?',ARRAY['SC3-1-u1-X13','SC3-1-u1-X17']::text[],false,'{"seq":12,"concept":"SC3-1-u1-C21","difficulty":2,"kind":"mc","stem":"귤과 배를 비교하니 배 쪽으로, 배와 사과를 비교하니 배 쪽으로 기울었어요. 가장 무거운 과일은 무엇인가요?","options":[{"t":"배","correct":true},{"t":"귤","mis":"SC3-1-u1-X13"},{"t":"사과","mis":"SC3-1-u1-X13"},{"t":"알 수 없어요","mis":"SC3-1-u1-X17"}],"explanation":["두 번 모두 어느 쪽이었나요?","배 쪽이에요.","배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
