INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#14','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C33',2,'mc','auto','고인돌의 무거운 윗돌을 옮긴 옛날 사람들의 방법에서 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u1-X28','SC3-1-u1-X05','SC3-1-u1-X25']::text[],false,'{"seq":14,"concept":"SC3-1-u1-C33","difficulty":2,"kind":"mc","stem":"고인돌의 무거운 윗돌을 옮긴 옛날 사람들의 방법에서 알 수 있는 것은 무엇인가요?","options":[{"t":"무거운 물체는 힘을 합치거나 도구를 써서 옮길 수 있다","correct":true},{"t":"무거운 물체는 한 사람이 맨손으로만 옮긴다","mis":"SC3-1-u1-X28"},{"t":"돌은 저절로 옮겨진다","mis":"SC3-1-u1-X05"},{"t":"도구를 쓰면 돌이 더 무거워진다","mis":"SC3-1-u1-X25"}],"explanation":["아주 무거운 돌이에요.","함께 또는 도구로요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
