INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#16','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C41',2,'mc','auto','입는 로봇이 지레·빗면 같은 도구가 발전한 모습이라고 하는 까닭은 무엇인가요?',ARRAY['SC3-1-u1-X36','SC3-1-u1-X26','SC3-1-u1-X34']::text[],false,'{"seq":16,"concept":"SC3-1-u1-C41","difficulty":2,"kind":"mc","stem":"입는 로봇이 지레·빗면 같은 도구가 발전한 모습이라고 하는 까닭은 무엇인가요?","options":[{"t":"작은 힘으로 무거운 물체를 들게 돕기 때문에","correct":true},{"t":"무게를 정확히 재기 때문에","mis":"SC3-1-u1-X36"},{"t":"비스듬한 면이 있기 때문에","mis":"SC3-1-u1-X26"},{"t":"힘이 더 들게 하기 때문에","mis":"SC3-1-u1-X34"}],"explanation":["도구가 하는 일이에요.","작은 힘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#17','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C4',3,'mc','auto','반죽을 손으로 누르면 납작해지고, 공을 차면 굴러가요. 두 일의 같은 점은 무엇인가요?',ARRAY['SC3-1-u1-X04','SC3-1-u1-X05','SC3-1-u1-X37']::text[],false,'{"seq":17,"concept":"SC3-1-u1-C4","difficulty":3,"kind":"mc","stem":"반죽을 손으로 누르면 납작해지고, 공을 차면 굴러가요. 두 일의 같은 점은 무엇인가요?","options":[{"t":"힘을 받아 물체에 변화가 생겼다","correct":true},{"t":"아무 변화가 없었다","mis":"SC3-1-u1-X04"},{"t":"둘 다 저절로 일어났다","mis":"SC3-1-u1-X05"},{"t":"힘이 눈에 보였다","mis":"SC3-1-u1-X37"}],"explanation":["모양과 움직임이에요.","변화가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
