INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#19','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C19',3,'mc','auto','수평대 양쪽 같은 거리에 물체를 올렸더니 수평을 이루었어요. 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u1-X16','SC3-1-u1-X12','SC3-1-u1-X15']::text[],false,'{"seq":19,"concept":"SC3-1-u1-C19","difficulty":3,"kind":"mc","stem":"수평대 양쪽 같은 거리에 물체를 올렸더니 수평을 이루었어요. 알 수 있는 것은 무엇인가요?","options":[{"t":"두 물체의 무게가 같아요","correct":true},{"t":"왼쪽 물체가 더 무거워요","mis":"SC3-1-u1-X16"},{"t":"크기가 큰 물체가 더 무거워요","mis":"SC3-1-u1-X12"},{"t":"수평대가 고장 났어요","mis":"SC3-1-u1-X15"}],"explanation":["기울지 않았어요.","무게가 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#20','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C25',3,'mc','auto','g과 kg은 무엇을 나타내는 단위인가요?',ARRAY['SC3-1-u1-X21']::text[],false,'{"seq":20,"concept":"SC3-1-u1-C25","difficulty":3,"kind":"mc","stem":"g과 kg은 무엇을 나타내는 단위인가요?","options":[{"t":"무게","correct":true},{"t":"길이","mis":"SC3-1-u1-X21"},{"t":"들이","mis":"SC3-1-u1-X21"},{"t":"시간","mis":"SC3-1-u1-X21"}],"explanation":["그램과 킬로그램이에요.","저울로 재요.","무게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#21','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C33',3,'mc','auto','혼자 들 수 없는 무거운 책상을 옮겨야 해요. 알맞은 방법은 무엇인가요?',ARRAY['SC3-1-u1-X28','SC3-1-u1-X29','SC3-1-u1-X05']::text[],false,'{"seq":21,"concept":"SC3-1-u1-C33","difficulty":3,"kind":"mc","stem":"혼자 들 수 없는 무거운 책상을 옮겨야 해요. 알맞은 방법은 무엇인가요?","options":[{"t":"여러 친구와 힘을 합쳐 함께 옮겨요","correct":true},{"t":"혼자 맨손으로 끝까지 들어요","mis":"SC3-1-u1-X28"},{"t":"책상을 발로 차서 옮겨요","mis":"SC3-1-u1-X29"},{"t":"책상이 저절로 움직이기를 기다려요","mis":"SC3-1-u1-X05"}],"explanation":["고인돌을 떠올려요.","힘을 합쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#22','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C41',3,'mc','auto','도구가 발전해 온 모습으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u1-X34','SC3-1-u1-X36','SC3-1-u1-X32']::text[],false,'{"seq":22,"concept":"SC3-1-u1-C41","difficulty":3,"kind":"mc","stem":"도구가 발전해 온 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"지레·빗면에서 힘을 더해 주는 입는 로봇까지 나왔어요","correct":true},{"t":"도구는 쓸수록 힘을 더 들게 해요","mis":"SC3-1-u1-X34"},{"t":"입는 로봇은 도구와 관계없어요","mis":"SC3-1-u1-X36"},{"t":"지레와 빗면은 이제 쓰지 않아요","mis":"SC3-1-u1-X32"}],"explanation":["단원을 돌아봐요.","로봇까지 왔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#23','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C31',4,'mc','auto','친구가 「경사로로 밀어 올리면 곧장 들어 올리는 것보다 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X25','SC3-1-u1-X26','SC3-1-u1-X29']::text[],false,'{"seq":23,"concept":"SC3-1-u1-C31","difficulty":4,"kind":"mc","stem":"친구가 「경사로로 밀어 올리면 곧장 들어 올리는 것보다 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「빗면인 경사로를 이용하면 곧장 들어 올릴 때보다 작은 힘이 들어.」","correct":true},{"t":"「맞아, 힘이 더 들어.」","mis":"SC3-1-u1-X25"},{"t":"「경사로는 지레야.」","mis":"SC3-1-u1-X26"},{"t":"「맨손으로 던져 올리는 게 좋아.」","mis":"SC3-1-u1-X29"}],"explanation":["주스 통을 떠올려요.","작은 힘이었어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#24','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C39',4,'mc','auto','친구가 「입는 로봇을 입으면 오히려 몸이 무거워져 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u1-X34','SC3-1-u1-X33','SC3-1-u1-X36']::text[],false,'{"seq":24,"concept":"SC3-1-u1-C39","difficulty":4,"kind":"mc","stem":"친구가 「입는 로봇을 입으면 오히려 몸이 무거워져 힘이 더 들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「입는 로봇이 힘을 더해 주어 무거운 물건도 작은 힘으로 들 수 있어.」","correct":true},{"t":"「맞아, 힘이 더 들어.」","mis":"SC3-1-u1-X34"},{"t":"「입는 로봇은 사람 없이 혼자 일해.」","mis":"SC3-1-u1-X33"},{"t":"「입는 로봇은 무게를 재는 기계야.」","mis":"SC3-1-u1-X36"}],"explanation":["로봇이 하는 일이에요.","힘을 더해 줘요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u1_review_d#25','sci',3,1,'u1','','g3_1_sci_u1_review_d','unit_review','SC3-1-u1-C31',4,'essay','teacher','새봄반 일지 ⑥을 보고 돌과 수레를 옮길 때 쓴 도구 이름을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u1-C31","difficulty":4,"kind":"essay","stem":"새봄반 일지 ⑥을 보고 돌과 수레를 옮길 때 쓴 도구 이름을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 돌을 들 때는 지레를, 수레를 올릴 때는 빗면을 썼다. 맨손으로는 꿈쩍 않던 돌이 지레로 들렸듯이 도구를 쓰면 작은 힘으로 무거운 물체를 옮길 수 있다.","scoring_points":["돌 — 지레라고 썼는가","수레 — 빗면이라고 썼는가","도구를 쓰면 작은 힘이 든다고 친구 다의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","막대와 판자예요.","고쳐 써요."],"asset":{"type":"passage","lines":["무거운 돌을 맨손으로 들려니 꿈쩍도 하지 않았다.","긴 막대를 받침대에 걸치고 막대 끝을 눌렀더니 돌이 들렸다.","무거운 수레는 비스듬한 판자를 따라 밀어 올렸다.","친구 다 — 「도구를 쓰면 힘이 더 들어.」"],"title":"새봄반 일지 ⑥ 무거운 돌 옮기기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
